L["Changed fields: %d"] = "Изменено полей: %d"
-- en: "Compare"
L["Compare"] = "Сравнить"
-- en: "Read-only"
L["Read-only"] = "Только чтение"
-- en: "Imported item set"
L["Imported item set"] = "Импортированный комплект"
-- en: "Drag to reorder"
L["Drag to reorder"] = "Перетащите для изменения порядка"
-- en: "Item ID: %s"
L["Item ID: %s"] = "ID предмета: %s"
-- en: "Item reference: %s"
L["Item reference: %s"] = "Ссылка на предмет: %s"
-- en: "Built-in"
L["Built-in"] = "Встроенное"
-- en: "Built-in condition"
L["Built-in condition"] = "Встроенное условие"
-- en: "Custom condition"
