L["Alias"] = "Псевдоним"
-- en: "This alias is already in use."
L["This alias is already in use."] = "Этот псевдоним уже используется."
-- en: "Function"
L["Function"] = "Функция"
-- en: "Add binding"
L["Add binding"] = "Добавить привязку"
-- en: "Packaged source is read-only. Duplicate it to create an editable custom function."
L["Packaged source is read-only. Duplicate it to create an editable custom function."] = "Поставляемый исходный код доступен только для чтения. Дублируйте его, чтобы создать редактируемую пользовательскую функцию."
-- en: "Arguments become Lua parameters. Bindings expose selected helpers under explicit local aliases. Editing an alias does not rewrite your Lua body."
L["Arguments become Lua parameters. Bindings expose selected helpers under explicit local aliases. Editing an alias does not rewrite your Lua body."] = "Аргументы становятся параметрами Lua. Привязки открывают выбранных помощников под явными локальными псевдонимами. Правка псевдонима не переписывает тело Lua."
-- en: "New function"
L["New function"] = "Новая функция"
-- en: "Describe what this function does."
L["Describe what this function does."] = "Опишите, что делает эта функция."
-- en: "Add a function or duplicate a packaged helper to edit its source."
L["Add a function or duplicate a packaged helper to edit its source."] = "Добавьте функцию или дублируйте поставляемого помощника, чтобы править его код."
-- en: "LuaWorkbench supplies editing, completion, API knowledge and debugging. Debug runs this buffer explicitly using the test arguments. It does not replace the saved rotation or live callback."
L["LuaWorkbench supplies editing, completion, API knowledge and debugging. Debug runs this buffer explicitly using the test arguments. It does not replace the saved rotation or live callback."] = "LuaWorkbench обеспечивает правку, автодополнение, знание API и отладку. «Отладка» явно запускает этот буфер с тестовыми аргументами. Сохранённая ротация и действующий обратный вызов не заменяются."
-- en: "Test arguments"
L["Test arguments"] = "Тестовые аргументы"
-- en: "API knowledge"
L["API knowledge"] = "Знание API"
-- en: "Test arguments must be a Lua table."
L["Test arguments must be a Lua table."] = "Тестовые аргументы должны быть таблицей Lua."
-- en: "Connected: embedded editing, completion, API knowledge and debugging."
L["Connected: embedded editing, completion, API knowledge and debugging."] = "Подключено: встроенная правка, автодополнение, знание API и отладка."
-- en: "Review the dependency bundle before applying it."
L["Review the dependency bundle before applying it."] = "Проверьте пакет зависимостей перед применением."
-- en: "Function bindings (%d)"
L["Function bindings (%d)"] = "Привязки функций (%d)"
-- en: "Aliases are local names in your Lua body. Changing an alias does not rewrite the body."
L["Aliases are local names in your Lua body. Changing an alias does not rewrite the body."] = "Псевдонимы — это локальные имена в теле Lua. Смена псевдонима не переписывает тело."
-- en: "Reuse existing"
L["Reuse existing"] = "Использовать существующее"
-- en: "Replace existing"
L["Replace existing"] = "Заменить существующее"
-- en: "Import with new identifier"
L["Import with new identifier"] = "Импортировать с новым идентификатором"
-- en: "Create"
L["Create"] = "Создать"
-- en: "Review source"
L["Review source"] = "Проверить исходный код"
-- en: "Original identifier"
L["Original identifier"] = "Исходный идентификатор"
-- en: "Destination identifier"
L["Destination identifier"] = "Идентификатор назначения"
-- en: "Callback"
L["Callback"] = "Обратный вызов"
-- en: "Include custom function dependencies"
L["Include custom function dependencies"] = "Включить зависимости от пользовательских функций"
-- en: "Review import"
L["Review import"] = "Проверить импорт"
-- en: "Apply import"
L["Apply import"] = "Применить импорт"
-- en: "Function dependency bundle"
L["Function dependency bundle"] = "Пакет зависимостей функций"
-- en: "Review the complete bundle before applying an import. Imported Lua can execute when registered; only apply code you trust."
L["Review the complete bundle before applying an import. Imported Lua can execute when registered; only apply code you trust."] = "Проверьте весь пакет перед применением импорта. Импортированный Lua может выполняться при регистрации; применяйте только код, которому доверяете."
-- en: "Review each original name, destination and dependency below. Apply import saves the complete reviewed bundle."
L["Review each original name, destination and dependency below. Apply import saves the complete reviewed bundle."] = "Проверьте ниже каждое исходное имя, место назначения и зависимость. «Применить импорт» сохраняет весь проверенный пакет."
-- en: "Conflict action"
L["Conflict action"] = "Действие при конфликте"
-- en: "Imported name"
L["Imported name"] = "Импортированное имя"
-- en: "Existing dependents"
L["Existing dependents"] = "Зависящий код"
-- en: "This imported definition is disabled. Its dependents remain unavailable."
L["This imported definition is disabled. Its dependents remain unavailable."] = "Это импортированное определение отключено. Зависящий от него код остаётся недоступным."
-- en: "Required functions"
L["Required functions"] = "Необходимые функции"
-- en: "Paste a bundle above, then review its original names, destinations and required functions."
L["Paste a bundle above, then review its original names, destinations and required functions."] = "Вставьте пакет выше, затем проверьте его исходные имена, места назначения и необходимые функции."
-- en: "Filter Built In or Custom helpers and search their names, identifiers or descriptions. Packaged helpers show read-only source and typed documentation. Duplicate creates an editable copy with a new stable identifier. Argument and return rows document the Lua signature."
L["Filter Built In or Custom helpers and search their names, identifiers or descriptions. Packaged helpers show read-only source and typed documentation. Duplicate creates an editable copy with a new stable identifier. Argument and return rows document the Lua signature."] = "Отфильтруйте встроенных или пользовательских помощников и ищите по именам, идентификаторам или описаниям. Поставляемые помощники показывают исходный код только для чтения и типизированную документацию. «Дублировать» создаёт редактируемую копию с новым постоянным идентификатором. Строки аргументов и возвратов документируют сигнатуру Lua."
-- en: "Undo and Redo edit the Lua body. Reset restores the saved body or new-function template and can be undone. Check syntax executes no custom Lua. Apply saves the body and metadata together; Discard abandons the draft. Leaving with changes offers Apply, Discard or Cancel."
L["Undo and Redo edit the Lua body. Reset restores the saved body or new-function template and can be undone. Check syntax executes no custom Lua. Apply saves the body and metadata together; Discard abandons the draft. Leaving with changes offers Apply, Discard or Cancel."] = "«Отменить» и «Повторить» правят тело Lua. «Сбросить» восстанавливает сохранённое тело или шаблон новой функции, и это можно отменить. «Проверить синтаксис» не выполняет пользовательский Lua. «Применить» сохраняет тело и метаданные вместе; «Отменить изменения» отбрасывает черновик. При уходе с изменениями предлагается «Применить», «Отменить изменения» или «Отмена»."
-- en: "Expand Function bindings to add explicit helper aliases and choose their targets. Changing an alias does not rewrite your Lua body. Missing, disabled or invalid dependencies keep their dependents unavailable until repaired."
L["Expand Function bindings to add explicit helper aliases and choose their targets. Changing an alias does not rewrite your Lua body. Missing, disabled or invalid dependencies keep their dependents unavailable until repaired."] = "Разверните «Привязки функций», чтобы добавить явные псевдонимы помощников и выбрать их цели. Смена псевдонима не переписывает тело Lua. Отсутствующие, отключённые или некорректные зависимости оставляют зависящий код недоступным до исправления."
-- en: "Include custom function dependencies exports their source with the selected definition. Without it, the bundle records required helper identities and versions. Review source shows every imported Lua body. Resolve each original name and destination with Reuse, Replace or a new identifier. Apply import saves the complete reviewed bundle and can register imported Lua. Only apply code you trust."
L["Include custom function dependencies exports their source with the selected definition. Without it, the bundle records required helper identities and versions. Review source shows every imported Lua body. Resolve each original name and destination with Reuse, Replace or a new identifier. Apply import saves the complete reviewed bundle and can register imported Lua. Only apply code you trust."] = "«Включить зависимости от пользовательских функций» экспортирует их исходный код вместе с выбранным определением. Без этого пакет записывает идентичности и версии нужных помощников. «Проверить исходный код» показывает каждое импортируемое тело Lua. Для каждого исходного имени и места назначения выберите «Использовать», «Заменить» или новый идентификатор. «Применить импорт» сохраняет весь проверенный пакет и может зарегистрировать импортированный Lua. Применяйте только код, которому доверяете."
-- en: "Check"
L["Check"] = "Проверить"
-- en: "Live"
L["Live"] = "В реальном времени"
-- en: "Preview"
L["Preview"] = "Предпросмотр"
-- en: "The preview failed. Use /rm errors for details."
L["The preview failed. Use /rm errors for details."] = "Предпросмотр не удался. Подробности — /rm errors."
-- en: "Test values were not saved because they are not bounded plain data."
L["Test values were not saved because they are not bounded plain data."] = "Тестовые значения не сохранены, так как не являются ограниченными простыми данными."
-- en: "Condition check"
L["Condition check"] = "Проверка условия"
-- en: "Fields UI preview"
L["Fields UI preview"] = "Предпросмотр интерфейса полей"
-- en: "Help preview"
L["Help preview"] = "Предпросмотр справки"
-- en: "Edit detached test values below. Check validates them before evaluating. Live is opt-in; test values are saved separately from the condition source."
L["Edit detached test values below. Check validates them before evaluating. Live is opt-in; test values are saved separately from the condition source."] = "Измените отдельные тестовые значения ниже. «Проверить» проверяет их перед вычислением. Режим «В реальном времени» включается вручную; тестовые значения хранятся отдельно от исходного кода условия."
-- en: "Preview runs only this callback with detached sample values. It does not save or register the condition."
L["Preview runs only this callback with detached sample values. It does not save or register the condition."] = "Предпросмотр запускает только этот обратный вызов с отдельными образцами значений. Условие не сохраняется и не регистрируется."
-- en: "Complete the source fields before checking."
L["Complete the source fields before checking."] = "Перед проверкой заполните поля исходного кода."
-- en: "Check could not compile the current source. Fix the source before checking again."
L["Check could not compile the current source. Fix the source before checking again."] = "Не удалось скомпилировать текущий исходный код. Исправьте его и проверьте снова."
-- en: "Skipped: invalid test values"
L["Skipped: invalid test values"] = "Пропущено: некорректные тестовые значения"
-- en: "Validation: %s"
L["Validation: %s"] = "Проверка: %s"
-- en: "Passed"
L["Passed"] = "Пройдено"
-- en: "Evaluation: %s"
L["Evaluation: %s"] = "Вычисление: %s"
-- en: "Fields UI and Help offer an explicit Preview of the current callback. Preview uses detached sample values and the normal field or help renderer. It does not save, register, validate or evaluate the condition. Closing it releases its controls and returns to the source draft. Check syntax never runs a callback."
L["Fields UI and Help offer an explicit Preview of the current callback. Preview uses detached sample values and the normal field or help renderer. It does not save, register, validate or evaluate the condition. Closing it releases its controls and returns to the source draft. Check syntax never runs a callback."] = "«Интерфейс полей» и «Справка» предлагают явный предпросмотр текущего обратного вызова. Предпросмотр использует отдельные образцы значений и обычный отрисовщик полей или справки. Он не сохраняет, не регистрирует, не проверяет и не вычисляет условие. Закрытие освобождает его элементы и возвращает к черновику исходного кода. «Проверить синтаксис» никогда не запускает обратный вызов."
-- en: "Evaluate and Validate offer Check with the same Fields UI and detached sample values. Check runs validation first, then evaluates only valid values. Results show true, false or an unavailable reason. Live is opt-in and checks at most twice per second while this panel is shown; closing stops it. Test values are saved separately and never enter condition exports or rotation edits. Source changes run no callbacks unless you check again or enable Live."
L["Evaluate and Validate offer Check with the same Fields UI and detached sample values. Check runs validation first, then evaluates only valid values. Results show true, false or an unavailable reason. Live is opt-in and checks at most twice per second while this panel is shown; closing stops it. Test values are saved separately and never enter condition exports or rotation edits. Source changes run no callbacks unless you check again or enable Live."] = "«Вычисление» и «Проверка» предлагают «Проверить» с тем же интерфейсом полей и отдельными образцами значений. Сначала выполняется проверка, затем вычисляются только корректные значения. Результат — истина, ложь или причина недоступности. Режим «В реальном времени» включается вручную и проверяет не чаще двух раз в секунду, пока эта панель показана; закрытие останавливает его. Тестовые значения хранятся отдельно и никогда не попадают в экспорт условий или правки ротаций. Изменения исходного кода не запускают обратные вызовы, пока вы снова не проверите или не включите «В реальном времени»."
-- en: "Functions reference"
L["Functions reference"] = "Справочник функций"
-- en: "The Functions page documents public helpers and their typed arguments, return values and source. Context completion and hover use that reference; Ctrl-click a known helper to open its source. Use explicit binding aliases for reusable custom helpers."
L["The Functions page documents public helpers and their typed arguments, return values and source. Context completion and hover use that reference; Ctrl-click a known helper to open its source. Use explicit binding aliases for reusable custom helpers."] = "Страница «Функции» документирует общедоступных помощников, их типизированные аргументы, возвращаемые значения и исходный код. Контекстное автодополнение и всплывающие подсказки используют этот справочник; щелчок с Ctrl по известному помощнику открывает его код. Для многоразовых пользовательских помощников используйте явные псевдонимы привязок."
-- en: "The imported definition type does not match this editor."
L["The imported definition type does not match this editor."] = "Тип импортированного определения не соответствует этому редактору."
-- en: "Test values changed. Check again to refresh the result."
L["Test values changed. Check again to refresh the result."] = "Тестовые значения изменены. Проверьте снова, чтобы обновить результат."
-- en: "Complete the highlighted test inputs before checking."
L["Complete the highlighted test inputs before checking."] = "Перед проверкой заполните выделенные тестовые поля."
-- en: "Test"
L["Test"] = "Тест"
-- en: "Run test"
L["Run test"] = "Запустить тест"
-- en: "Test condition"
L["Test condition"] = "Тест условия"
-- en: "Debugger output"
L["Debugger output"] = "Вывод отладчика"
-- en: "Set test values in Test before debugging Evaluate."
L["Set test values in Test before debugging Evaluate."] = "Перед отладкой «Вычисления» задайте тестовые значения в «Тесте»."
-- en: "Debugger output uses a detached sample and the normal field or help container."
L["Debugger output uses a detached sample and the normal field or help container."] = "Вывод отладчика использует отдельный образец и обычный контейнер полей или справки."
-- en: "Choose test values in Fields UI, then Run test to validate and evaluate. Help is shown below the fields. Opening Test does not evaluate defaults. Live is opt-in."
L["Choose test values in Fields UI, then Run test to validate and evaluate. Help is shown below the fields. Opening Test does not evaluate defaults. Live is opt-in."] = "Выберите тестовые значения в «Интерфейсе полей», затем нажмите «Запустить тест» для проверки и вычисления. Справка показана под полями. Открытие «Теста» не вычисляет значения по умолчанию. Режим «В реальном времени» включается вручную."
-- en: "Test opens one condition-level dialog from any callback tab. It renders Fields UI and Help together with detached values. Choose the fields and Run test to validate, then evaluate only valid values. Opening the dialog does not evaluate defaults. Live is opt-in and stops when the dialog closes. Committed test values are available to the debugger and stay separate from source, exports and rotation edits. Check syntax never runs a callback."
L["Test opens one condition-level dialog from any callback tab. It renders Fields UI and Help together with detached values. Choose the fields and Run test to validate, then evaluate only valid values. Opening the dialog does not evaluate defaults. Live is opt-in and stops when the dialog closes. Committed test values are available to the debugger and stay separate from source, exports and rotation edits. Check syntax never runs a callback."] = "«Тест» открывает одно окно уровня условия с любой вкладки обратного вызова. В нём вместе показаны интерфейс полей и справка с отдельными значениями. Выберите поля и нажмите «Запустить тест» для проверки, после чего вычисляются только корректные значения. Открытие окна не вычисляет значения по умолчанию. Режим «В реальном времени» включается вручную и останавливается при закрытии окна. Подтверждённые тестовые значения доступны отладчику и хранятся отдельно от исходного кода, экспорта и правок ротации. «Проверить синтаксис» никогда не запускает обратный вызов."
-- en: "Nullable"
L["Nullable"] = "Допускает nil"
-- en: "Add return value"
L["Add return value"] = "Добавить возвращаемое значение"
-- en: "Lua returns multiple values in order. Each row documents one result."
L["Lua returns multiple values in order. Each row documents one result."] = "Lua возвращает несколько значений по порядку. Каждая строка документирует один результат."
-- en: "Expand code editor"
L["Expand code editor"] = "Развернуть редактор кода"
-- en: "Restore code editor"
L["Restore code editor"] = "Восстановить редактор кода"
-- en: "Choose a source helper and the local name used to call it in this Lua body. Renaming the local name does not rewrite code. Source modules distinguish helpers with the same name."
L["Choose a source helper and the local name used to call it in this Lua body. Renaming the local name does not rewrite code. Source modules distinguish helpers with the same name."] = "Выберите помощник-источник и локальное имя, под которым он вызывается в этом теле Lua. Переименование локального имени не переписывает код. Модули-источники различают помощников с одинаковыми именами."
-- en: "Local name in code"
L["Local name in code"] = "Локальное имя в коде"
-- en: "Source helper"
L["Source helper"] = "Помощник-источник"
-- en: "Function names use letters, numbers and underscores, beginning with a letter or underscore. Names suggest the local binding used to call them; registry identifiers stay stable."
L["Function names use letters, numbers and underscores, beginning with a letter or underscore. Names suggest the local binding used to call them; registry identifiers stay stable."] = "Имена функций состоят из латинских букв, цифр и подчёркиваний и начинаются с буквы или подчёркивания. Имена предлагают локальную привязку для вызова; идентификаторы в реестре остаются постоянными."
-- en: "This cannot be undone."
L["This cannot be undone."] = "Это нельзя отменить."
-- en: "Delete this announcement?"
L["Delete this announcement?"] = "Удалить это оповещение?"
-- en: "Type: %s"
L["Type: %s"] = "Тип: %s"
-- en: "Supported unit-token to localized unit-name lookup. Use value.unit as a key; for example addon.units[value.unit]. Available tokens vary by client."
L["Supported unit-token to localized unit-name lookup. Use value.unit as a key; for example addon.units[value.unit]. Available tokens vary by client."] = "Таблица соответствия поддерживаемых токенов юнитов и их локализованных названий. Используйте value.unit как ключ, например addon.units[value.unit]. Доступные токены зависят от клиента."
-- en: "Supported unit-token to localized possessive unit-name lookup, such as your target."
L["Supported unit-token to localized possessive unit-name lookup, such as your target."] = "Таблица соответствия поддерживаемых токенов юнитов и их локализованных притяжательных названий, например «вашей цели»."
-- en: "Rotation Master client compatibility adapter. Its methods return ordinary readable results or nil with a reason when an observation is unavailable. Use a colon call, or pass addon.Platform explicitly as self with a dot reference."
L["Rotation Master client compatibility adapter. Its methods return ordinary readable results or nil with a reason when an observation is unavailable. Use a colon call, or pass addon.Platform explicitly as self with a dot reference."] = "Адаптер совместимости клиентов Rotation Master. Его методы возвращают обычные читаемые результаты или nil с причиной, если наблюдение недоступно. Вызывайте через двоеточие или явно передавайте addon.Platform как self при обращении через точку."
-- en: "Rotation Master spell catalog for resolving client-specific spell IDs, ranks, names, icons and links."
L["Rotation Master spell catalog for resolving client-specific spell IDs, ranks, names, icons and links."] = "Каталог заклинаний Rotation Master для определения зависящих от клиента ID заклинаний, рангов, названий, иконок и ссылок."
-- en: "Utility functions explicitly bound to this condition or function. Choose a completion to bind an available custom function before inserting its reference."
L["Utility functions explicitly bound to this condition or function. Choose a completion to bind an available custom function before inserting its reference."] = "Вспомогательные функции, явно привязанные к этому условию или функции. Выберите вариант автодополнения, чтобы привязать доступную пользовательскую функцию перед вставкой ссылки на неё."
-- en: "Rotation Master custom function"
L["Rotation Master custom function"] = "Пользовательская функция Rotation Master"
-- en: "Rotation Master built-in function"
L["Rotation Master built-in function"] = "Встроенная функция Rotation Master"
-- en: "Rotation Master value"
L["Rotation Master value"] = "Значение Rotation Master"
-- en: "Global function (documentation unavailable on this client)"
L["Global function (documentation unavailable on this client)"] = "Глобальная функция (документация недоступна на этом клиенте)"
-- en: "This client does not provide signature documentation for this function. No arguments or return types have been inferred."
L["This client does not provide signature documentation for this function. No arguments or return types have been inferred."] = "Этот клиент не предоставляет документацию сигнатуры для этой функции. Аргументы и типы возвращаемых значений не выводились."
-- en: "Invoke"
L["Invoke"] = "Вызов"
-- en: "Functions are shared across profiles after Apply. Call custom utilities as functions.name(...); accepting completion adds the dependency binding. Typed calls need a binding under Function bindings. Built In examples show dot or colon explicitly."
L["Functions are shared across profiles after Apply. Call custom utilities as functions.name(...); accepting completion adds the dependency binding. Typed calls need a binding under Function bindings. Built In examples show dot or colon explicitly."] = "После применения функции общие для всех профилей. Вызывайте пользовательские утилиты как functions.name(...); принятие автодополнения добавляет привязку зависимости. Для набранных вручную вызовов нужна привязка в «Привязках функций». Примеры встроенных функций явно показывают точку или двоеточие."
-- en: "Show line numbers"
L["Show line numbers"] = "Показывать номера строк"
-- en: "Line-number visibility applies to every condition and function code editor."
L["Line-number visibility applies to every condition and function code editor."] = "Видимость номеров строк применяется ко всем редакторам кода условий и функций."
-- en: "Call a saved custom utility as functions.name(...). Accepting a completion attaches its stable dependency binding; for a typed call, choose its helper under Function bindings. Existing direct aliases still work. The Invoke example shows required addon dot or colon syntax for Built In functions. Renaming an alias does not rewrite source. Missing, disabled or invalid dependencies keep consumers unavailable."
L["Call a saved custom utility as functions.name(...). Accepting a completion attaches its stable dependency binding; for a typed call, choose its helper under Function bindings. Existing direct aliases still work. The Invoke example shows required addon dot or colon syntax for Built In functions. Renaming an alias does not rewrite source. Missing, disabled or invalid dependencies keep consumers unavailable."] = "Вызывайте сохранённую пользовательскую утилиту как functions.name(...). Принятие автодополнения добавляет её постоянную привязку зависимости; для набранного вручную вызова выберите помощника в «Привязках функций». Существующие прямые псевдонимы по-прежнему работают. Пример «Вызов» показывает обязательный синтаксис через точку или двоеточие для встроенных функций. Переименование псевдонима не переписывает исходный код. Отсутствующие, отключённые или некорректные зависимости оставляют использующий их код недоступным."
-- en: "Choose the editor for custom Lua conditions and functions. Show line numbers applies across code editors. Built In syntax highlighting and Plain text work without another addon. Automatic selects a connected provider or falls back safely. Apply saves settings; editor changes take effect on reopening, and line-number visibility updates open editors. LuaWorkbench and WowLua loading status is shown separately from integration availability."
L["Choose the editor for custom Lua conditions and functions. Show line numbers applies across code editors. Built In syntax highlighting and Plain text work without another addon. Automatic selects a connected provider or falls back safely. Apply saves settings; editor changes take effect on reopening, and line-number visibility updates open editors. LuaWorkbench and WowLua loading status is shown separately from integration availability."] = "Выберите редактор для пользовательских условий и функций Lua. «Показывать номера строк» действует во всех редакторах кода. Встроенная подсветка синтаксиса и простой текст работают без других аддонов. «Автоматически» выбирает подключённого поставщика или безопасно возвращается к встроенному. «Применить» сохраняет настройки; смена редактора вступает в силу при повторном открытии, а видимость номеров строк обновляется в открытых редакторах. Состояние загрузки LuaWorkbench и WowLua показывается отдельно от доступности интеграции."
-- en: "All namespaces"
L["All namespaces"] = "Все пространства имён"
-- en: "Call a utility as namespace.name(...). Built In namespaces follow source files; custom functions choose their Namespace. Accepting a completion attaches its stable dependency binding; for a typed call, add its qualified name under Function bindings. Namespaces do not supply self: the Invoke example includes a method receiver explicitly, and Existing API preserves its original dot or colon spelling. Existing aliases still work. Renaming a function or namespace does not rewrite existing code or bindings. Missing, disabled or invalid dependencies keep consumers unavailable."
L["Call a utility as namespace.name(...). Built In namespaces follow source files; custom functions choose their Namespace. Accepting a completion attaches its stable dependency binding; for a typed call, add its qualified name under Function bindings. Namespaces do not supply self: the Invoke example includes a method receiver explicitly, and Existing API preserves its original dot or colon spelling. Existing aliases still work. Renaming a function or namespace does not rewrite existing code or bindings. Missing, disabled or invalid dependencies keep consumers unavailable."] = "Вызывайте утилиту как namespace.name(...). Встроенные пространства имён соответствуют файлам исходного кода; пользовательские функции выбирают своё пространство имён. Принятие автодополнения добавляет постоянную привязку зависимости; для набранного вручную вызова добавьте его полное имя в «Привязки функций». Пространства имён не передают self: пример «Вызов» явно включает получателя метода, а «Существующий API» сохраняет исходное написание через точку или двоеточие. Существующие псевдонимы по-прежнему работают. Переименование функции или пространства имён не переписывает существующий код и привязки. Отсутствующие, отключённые или некорректные зависимости оставляют использующий их код недоступным."
-- en: "Choose a source helper and its name in this Lua body, such as custom.ready or utils.getCached. Namespaces are private to this callback. Renaming a binding does not rewrite code."
L["Choose a source helper and its name in this Lua body, such as custom.ready or utils.getCached. Namespaces are private to this callback. Renaming a binding does not rewrite code."] = "Выберите помощник-источник и его имя в этом теле Lua, например custom.ready или utils.getCached. Пространства имён закрыты для этого обратного вызова. Переименование привязки не переписывает код."
-- en: "Debug current buffer"
L["Debug current buffer"] = "Отладить текущий буфер"
-- en: "Debugger terminal"
L["Debugger terminal"] = "Терминал отладчика"
-- en: "Existing API"
L["Existing API"] = "Существующий API"
-- en: "Name in code"
L["Name in code"] = "Имя в коде"
-- en: "Namespace"
L["Namespace"] = "Пространство имён"
-- en: "Namespaces group functions; they do not supply a receiver. Accept a completion to bind the shown dotted call. For a typed call, add the same qualified name under Function bindings. Method examples include the required receiver explicitly. Functions are shared across profiles after Apply."
L["Namespaces group functions; they do not supply a receiver. Accept a completion to bind the shown dotted call. For a typed call, add the same qualified name under Function bindings. Method examples include the required receiver explicitly. Functions are shared across profiles after Apply."] = "Пространства имён группируют функции; они не передают получателя. Примите автодополнение, чтобы привязать показанный вызов через точку. Для набранного вручную вызова добавьте то же полное имя в «Привязки функций». Примеры методов явно включают обязательного получателя. После применения функции общие для всех профилей."
-- en: "Play runs the current buffer once without debugging. Condition callbacks use the fields configured in Test; functions use Test arguments. Returns, printed output and full errors are available in Output. Running does not apply source changes or replace the live callback."
L["Play runs the current buffer once without debugging. Condition callbacks use the fields configured in Test; functions use Test arguments. Returns, printed output and full errors are available in Output. Running does not apply source changes or replace the live callback."] = "«Воспроизвести» один раз запускает текущий буфер без отладки. Обратные вызовы условий используют поля, настроенные в «Тесте»; функции — тестовые аргументы. Возвращаемые значения, напечатанный вывод и полные ошибки доступны в «Выводе». Запуск не применяет изменения исходного кода и не заменяет действующий обратный вызов."
-- en: "Private utility-function namespace. It contains only explicit bindings for this callback."
L["Private utility-function namespace. It contains only explicit bindings for this callback."] = "Закрытое пространство имён вспомогательных функций. Содержит только явные привязки для этого обратного вызова."
-- en: "Run current buffer"
L["Run current buffer"] = "Запустить текущий буфер"
-- en: "The Debug button starts a separate session and pauses at the first executable line or breakpoint. Continue resumes execution, Step over advances past the current operation, and Step into enters instrumented script functions. Native functions cannot be stepped into. Stop ends the session. F5 continues, F10 steps over, F11 steps into, and Shift+F5 stops."
L["The Debug button starts a separate session and pauses at the first executable line or breakpoint. Continue resumes execution, Step over advances past the current operation, and Step into enters instrumented script functions. Native functions cannot be stepped into. Stop ends the session. F5 continues, F10 steps over, F11 steps into, and Shift+F5 stops."] = "Кнопка «Отладка» начинает отдельный сеанс и приостанавливается на первой исполняемой строке или точке останова. «Продолжить» возобновляет выполнение, «Шаг с обходом» проходит текущую операцию, а «Шаг с заходом» входит в инструментированные функции скрипта. Во встроенные функции зайти нельзя. «Стоп» завершает сеанс. F5 — продолжить, F10 — шаг с обходом, F11 — шаг с заходом, Shift+F5 — стоп."
-- en: "The debugger terminal appears below the code while debugging. When paused, enter expressions or assignments to inspect or change the current variables. The drawer button hides or shows the terminal. Output provides a copyable report of printed output, terminal evaluations and complete errors."
L["The debugger terminal appears below the code while debugging. When paused, enter expressions or assignments to inspect or change the current variables. The drawer button hides or shows the terminal. Output provides a copyable report of printed output, terminal evaluations and complete errors."] = "Во время отладки под кодом появляется терминал отладчика. На паузе вводите выражения или присваивания, чтобы изучить или изменить текущие переменные. Кнопка панели скрывает или показывает терминал. «Вывод» содержит копируемый отчёт с напечатанным выводом, вычислениями в терминале и полными ошибками."
-- en: "Argument"
L["Argument"] = "Аргумент"
-- en: "Arguments and returns"
L["Arguments and returns"] = "Аргументы и возвращаемые значения"
-- en: "Bindings (%d)"
L["Bindings (%d)"] = "Привязки (%d)"
-- en: "Call a utility as namespace.name(...). Built In namespaces follow source files; custom functions choose their Namespace. Accepting a completion attaches its stable dependency binding; for a typed call, add its qualified name under Function bindings. Namespaces do not supply self. Pass a method receiver explicitly in a namespaced dot call; object:method(x) is Lua shorthand for object.method(object, x). Existing addon APIs remain compatible with saved definitions. Existing aliases still work. Renaming a function or namespace does not rewrite existing code or bindings. Missing, disabled or invalid dependencies keep consumers unavailable."
L["Call a utility as namespace.name(...). Built In namespaces follow source files; custom functions choose their Namespace. Accepting a completion attaches its stable dependency binding; for a typed call, add its qualified name under Function bindings. Namespaces do not supply self. Pass a method receiver explicitly in a namespaced dot call; object:method(x) is Lua shorthand for object.method(object, x). Existing addon APIs remain compatible with saved definitions. Existing aliases still work. Renaming a function or namespace does not rewrite existing code or bindings. Missing, disabled or invalid dependencies keep consumers unavailable."] = "Вызывайте утилиту как namespace.name(...). Встроенные пространства имён соответствуют файлам исходного кода; пользовательские функции выбирают своё пространство имён. Принятие автодополнения добавляет постоянную привязку зависимости; для набранного вручную вызова добавьте его полное имя в «Привязки функций». Пространства имён не передают self. В вызове через точку из пространства имён передавайте получателя метода явно; object:method(x) — сокращение Lua для object.method(object, x). Существующие API аддона остаются совместимыми с сохранёнными определениями. Существующие псевдонимы по-прежнему работают. Переименование функции или пространства имён не переписывает существующий код и привязки. Отсутствующие, отключённые или некорректные зависимости оставляют использующий их код недоступным."
-- en: "Changing argument or return order can break existing callers. Rotation Master will not rewrite their Lua code. Continue?"
L["Changing argument or return order can break existing callers. Rotation Master will not rewrite their Lua code. Continue?"] = "Изменение порядка аргументов или возвращаемых значений может сломать существующие вызовы. Rotation Master не будет переписывать их код Lua. Продолжить?"
-- en: "Choose an existing namespace from the suggestions or type a new dotted namespace. Built In namespaces follow source files; custom namespaces are implied by saved functions and need no separate maintenance."
L["Choose an existing namespace from the suggestions or type a new dotted namespace. Built In namespaces follow source files; custom namespaces are implied by saved functions and need no separate maintenance."] = "Выберите существующее пространство имён из подсказок или введите новое через точку. Встроенные пространства имён соответствуют файлам исходного кода; пользовательские пространства имён определяются сохранёнными функциями и не требуют отдельного обслуживания."
-- en: "Click an Arguments or Returns heading to collapse or expand it. + Argument and + Return append when clicked, or insert at a highlighted gap when dragged. Drag a row or use Up / Down to reorder; Ctrl-drag carries following rows. The trash can removes a row. Type and Nullable document accepted values; Description explains each input or result. Lua can return several ordered results. Reordering a saved function warns because positional callers may need changes; RM does not rewrite call sites."
L["Click an Arguments or Returns heading to collapse or expand it. + Argument and + Return append when clicked, or insert at a highlighted gap when dragged. Drag a row or use Up / Down to reorder; Ctrl-drag carries following rows. The trash can removes a row. Type and Nullable document accepted values; Description explains each input or result. Lua can return several ordered results. Reordering a saved function warns because positional callers may need changes; RM does not rewrite call sites."] = "Нажмите на заголовок «Аргументы» или «Возвращаемые значения», чтобы свернуть или развернуть его. «+ Аргумент» и «+ Возврат» добавляют в конец при нажатии или вставляют в выделенный промежуток при перетаскивании. Перетаскивайте строку или используйте «Вверх» / «Вниз» для изменения порядка; с Ctrl переносятся и следующие строки. Корзина удаляет строку. «Тип» и «Допускает nil» документируют допустимые значения; «Описание» поясняет каждый вход или результат. Lua может возвращать несколько упорядоченных результатов. При изменении порядка у сохранённой функции появляется предупреждение, так как позиционные вызовы могут потребовать правки; RM не переписывает места вызова."
-- en: "Function names use letters, numbers and underscores, beginning with a letter or underscore. The code signature shows the qualified namespace.name used by callers."
L["Function names use letters, numbers and underscores, beginning with a letter or underscore. The code signature shows the qualified namespace.name used by callers."] = "Имена функций состоят из латинских букв, цифр и подчёркиваний и начинаются с буквы или подчёркивания. Сигнатура кода показывает полное namespace.name, используемое при вызове."
-- en: "Return"
L["Return"] = "Возврат"
-- en: "Search helpers by name or description, then filter Built In / Custom and namespace. Packaged helpers use the same read-only pane. Duplicate creates an editable custom copy."
L["Search helpers by name or description, then filter Built In / Custom and namespace. Packaged helpers use the same read-only pane. Duplicate creates an editable custom copy."] = "Ищите помощников по имени или описанию, затем фильтруйте по «Встроенные» / «Свои» и пространству имён. Поставляемые помощники используют ту же панель только для чтения. «Дублировать» создаёт редактируемую пользовательскую копию."
-- en: "Changing argument order can break existing callers. Rotation Master will not rewrite their Lua code. Continue?"
L["Changing argument order can break existing callers. Rotation Master will not rewrite their Lua code. Continue?"] = "Изменение порядка аргументов может сломать существующие вызовы. Rotation Master не будет переписывать их код Lua. Продолжить?"
-- en: "Changing return documentation order does not rewrite return statements or existing callers. Review the Lua body and callers for the new order. Continue?"
L["Changing return documentation order does not rewrite return statements or existing callers. Review the Lua body and callers for the new order. Continue?"] = "Изменение порядка в документации возвращаемых значений не переписывает операторы return и существующие вызовы. Проверьте тело Lua и вызовы на соответствие новому порядку. Продолжить?"
-- en: "Click an Arguments or Returns heading to collapse or expand it. + Argument and + Return append when clicked, or insert at a highlighted gap when dragged. Drag a row or use Up / Down to reorder; Ctrl-drag carries following rows. The trash can removes a row. Type and Nullable document accepted values; Description explains each input or result. Lua can return several ordered results. Return rows describe those results; moving them does not rewrite return statements. Reordering a saved function warns because positional callers may need changes; RM does not rewrite call sites."
L["Click an Arguments or Returns heading to collapse or expand it. + Argument and + Return append when clicked, or insert at a highlighted gap when dragged. Drag a row or use Up / Down to reorder; Ctrl-drag carries following rows. The trash can removes a row. Type and Nullable document accepted values; Description explains each input or result. Lua can return several ordered results. Return rows describe those results; moving them does not rewrite return statements. Reordering a saved function warns because positional callers may need changes; RM does not rewrite call sites."] = "Нажмите на заголовок «Аргументы» или «Возвращаемые значения», чтобы свернуть или развернуть его. «+ Аргумент» и «+ Возврат» добавляют в конец при нажатии или вставляют в выделенный промежуток при перетаскивании. Перетаскивайте строку или используйте «Вверх» / «Вниз» для изменения порядка; с Ctrl переносятся и следующие строки. Корзина удаляет строку. «Тип» и «Допускает nil» документируют допустимые значения; «Описание» поясняет каждый вход или результат. Lua может возвращать несколько упорядоченных результатов. Строки возврата описывают эти результаты; их перемещение не переписывает операторы return. При изменении порядка у сохранённой функции появляется предупреждение, так как позиционные вызовы могут потребовать правки; RM не переписывает места вызова."
-- en: "Card controls"
L["Card controls"] = "Элементы карточки"
-- en: "Describe this value for function documentation, completion and hover help. Changes remain in the draft until Apply."
L["Describe this value for function documentation, completion and hover help. Changes remain in the draft until Apply."] = "Опишите это значение для документации функции, автодополнения и всплывающих подсказок. Изменения остаются в черновике до нажатия «Применить»."
-- en: "Drag a card to reorder arguments; Ctrl-drag includes following arguments. Up and down move one position. Duplicate copies the argument with a unique name; the trash can removes it. Reordering a saved function requires confirmation because existing callers are not rewritten."
L["Drag a card to reorder arguments; Ctrl-drag includes following arguments. Up and down move one position. Duplicate copies the argument with a unique name; the trash can removes it. Reordering a saved function requires confirmation because existing callers are not rewritten."] = "Перетаскивайте карточку, чтобы менять порядок аргументов; с Ctrl переносятся и следующие аргументы. «Вверх» и «Вниз» сдвигают на одну позицию. «Дублировать» копирует аргумент с уникальным именем; корзина удаляет его. Изменение порядка у сохранённой функции требует подтверждения, так как существующие вызовы не переписываются."
-- en: "Drag a card to reorder return documentation; Ctrl-drag includes following returns. Up and down move one position. Duplicate copies the documented return value; the trash can removes it. Return order in this list does not rewrite return statements or callers."
L["Drag a card to reorder return documentation; Ctrl-drag includes following returns. Up and down move one position. Duplicate copies the documented return value; the trash can removes it. Return order in this list does not rewrite return statements or callers."] = "Перетаскивайте карточку, чтобы менять порядок документации возвращаемых значений; с Ctrl переносятся и следующие. «Вверх» и «Вниз» сдвигают на одну позицию. «Дублировать» копирует описанное возвращаемое значение; корзина удаляет его. Порядок в этом списке не переписывает операторы return и вызовы."
-- en: "Preview rendered. Use Output for printed messages."
L["Preview rendered. Use Output for printed messages."] = "Предпросмотр отрисован. Напечатанные сообщения — в «Выводе»."
-- en: "Rendered output appears here when the callback runs or steps through widget creation."
L["Rendered output appears here when the callback runs or steps through widget creation."] = "Здесь появится отрисованный результат, когда обратный вызов выполнится или пошагово пройдёт создание виджета."
-- en: "Set values in Test before running or debugging this condition."
L["Set values in Test before running or debugging this condition."] = "Перед запуском или отладкой этого условия задайте значения в «Тесте»."
-- en: "The argument name is the local parameter available in the Lua body. Use a valid Lua identifier. Renaming this documentation does not rewrite references in the code."
L["The argument name is the local parameter available in the Lua body. Use a valid Lua identifier. Renaming this documentation does not rewrite references in the code."] = "Имя аргумента — локальный параметр, доступный в теле Lua. Используйте допустимый идентификатор Lua. Переименование в документации не переписывает ссылки в коде."
-- en: "Type and Nullable describe the values accepted or returned by this function. They document the contract; they do not rewrite or validate values in the Lua body."
L["Type and Nullable describe the values accepted or returned by this function. They document the contract; they do not rewrite or validate values in the Lua body."] = "«Тип» и «Допускает nil» описывают значения, которые функция принимает или возвращает. Они документируют контракт и не переписывают и не проверяют значения в теле Lua."
-- en: "Enable Rotation Master recommendations, automatic rotation switching and bound item-set updates. Disabling clears active advice and highlights and hides the preview. Apply saves the change."
L["Help.General.enable"] = "Включить рекомендации Rotation Master, автопереключение ротаций и обновление привязанных комплектов предметов. Отключение очищает текущие советы и подсветку и скрывает предпросмотр. «Применить» сохраняет изменение."
-- en: "Set how often Rotation Master reevaluates the active rotation and independent cooldowns, in seconds. A shorter interval updates advice more often and uses more processing time. It does not cast spells, queue actions, or predict future combat."
L["Help.General.poll"] = "Задайте, как часто (в секундах) Rotation Master перевычисляет активную ротацию и независимые восстановления. Более короткий интервал чаще обновляет советы и потребляет больше вычислительного времени. Заклинания не применяются, действия не ставятся в очередь, будущий бой не прогнозируется."
-- en: "Out of combat with no target and no focus, Rotation Master skips a polling tick unless something it watches has changed: auras, cooldowns, health or power of you, your pet or party, movement, casting, equipment, bags, form, pets or group. It still re-checks at least this often, for time-based conditions (aura or cooldown remaining), distance, and custom code. In combat, with any target or focus, or while configuration is open, every polling tick is evaluated. Zero evaluates every polling tick."
L["Help.General.idle_poll"] = "Вне боя, без цели и фокуса Rotation Master пропускает такт опроса, если не изменилось ничего из отслеживаемого: эффекты, восстановления, здоровье или ресурс у вас, питомца или группы, движение, применение заклинаний, экипировка, сумки, облик, питомцы или группа. Он всё равно перепроверяет хотя бы с этой частотой — для условий по времени (оставшееся время эффекта или восстановления), дистанции и пользовательского кода. В бою, при наличии цели или фокуса, а также при открытых настройках вычисляется каждый такт опроса. Ноль — вычислять каждый такт."
-- en: "With automatic switching, Rotation Master checks this often, in and out of combat, whether a different rotation's switch conditions now match, so conditions that change on their own (nearby enemy count, threat, movement, health) take effect. Target, focus and pet changes are checked straight away. Zero turns automatic switching off. Choosing a rotation manually still overrides automatic switching until you choose Auto again."
L["Help.General.autoswitch_poll"] = "При автопереключении Rotation Master с этой частотой, в бою и вне его, проверяет, не совпали ли теперь условия переключения другой ротации, чтобы срабатывали условия, меняющиеся сами по себе (число противников рядом, угроза, движение, здоровье). Смена цели, фокуса и питомца проверяется сразу. Ноль отключает автопереключение. Ручной выбор ротации по-прежнему имеет приоритет над автопереключением, пока вы снова не выберете «Авто»."
-- en: "Keep Rotation Master from automatically selecting another rotation from its switch condition. This preference survives reloads. Manually choosing a rotation with /rm set <rotation> also suspends automatic switching until you choose automatic selection again."
L["Help.General.disable_autoswitch"] = "Не давать Rotation Master автоматически выбирать другую ротацию по её условию переключения. Настройка сохраняется после перезагрузки. Ручной выбор ротации через /rm set <rotation> также приостанавливает автопереключение, пока вы снова не выберете автоматический выбор."
-- en: "Hide the main rotation recommendation on action bars. Independent cooldown highlights remain available. Enable Preview Spells if you want to see the main advice in a separate window; with both displays off, the main recommendation has no visible icon."
L["Help.General.disable_buttons"] = "Скрыть основную рекомендацию ротации на панелях команд. Подсветка независимых восстановлений остаётся. Включите «Предпросмотр заклинаний», чтобы видеть основной совет в отдельном окне; если отключены оба способа, у основной рекомендации нет видимой иконки."
-- en: "Set the refresh interval for condition status while editing, in seconds. Zero turns off periodic status updates. This is separate from the recommendation polling interval and does not enable live condition testing unless you explicitly choose it."
L["Help.General.live_config_update"] = "Задайте интервал обновления состояния условий при правке (в секундах). Ноль отключает периодическое обновление. Он не зависит от интервала опроса рекомендаций и не включает тестирование условий в реальном времени, если вы явно его не выберете."
-- en: "Show the Rotation Master minimap icon. Left-click toggles the configuration window. Right-click opens the quick menu for enabling recommendations and choosing a rotation or automatic switching."
L["Help.General.minimap"] = "Показывать значок Rotation Master у миникарты. Левый щелчок открывает или закрывает окно настроек. Правый щелчок открывает быстрое меню для включения рекомендаций и выбора ротации или автопереключения."
-- en: "Choose Diagram or List as the starting rotation view. This profile preference applies when opening a rotation; changing the view inside the editor does not change this setting. Cooldowns always use a scrolling grid."
L["Help.General.rotation_view"] = "Выберите «Схема» или «Список» как начальный вид ротации. Эта настройка профиля применяется при открытии ротации; смена вида в редакторе её не меняет. Восстановления всегда отображаются прокручиваемой сеткой."
-- en: "Choose how many seconds of previous spell casts to retain for history-based conditions. Older casts are removed as recommendations update. A longer history retains more records."
L["Help.General.spell_history"] = "Выберите, сколько секунд истории применённых заклинаний хранить для условий по истории. Более старые применения удаляются при обновлении рекомендаций. Более длинная история хранит больше записей."
-- en: "Choose how many seconds of combat events to retain for conditions such as recent hits, parries and blocks. Older events are removed as recommendations update. Availability depends on the client combat-data policy."
L["Help.General.combat_history"] = "Выберите, сколько секунд боевых событий хранить для условий вроде недавних попаданий, парирований и блоков. Более старые события удаляются при обновлении рекомендаций. Доступность зависит от политики клиента по боевым данным."
-- en: "Choose how many seconds of observed damage and healing to retain for burn-rate and time-to-die estimates. Recent observations receive more weight. A longer window uses more records and smooths short changes; it cannot supply events the client does not expose."
L["Help.General.damage_history"] = "Выберите, сколько секунд наблюдаемого урона и исцеления хранить для оценок скорости потери здоровья и времени до смерти. Недавние наблюдения имеют больший вес. Более длинное окно использует больше записей и сглаживает короткие изменения; события, которые клиент не предоставляет, оно восполнить не может."
-- en: "Choose a whole number of upcoming recommendations, from zero (hidden) to five. The preview shows current priority results, not a simulation of future cooldowns or combat. Icons start at 64 pixels; resizing scales all icons while preserving their square shape and the window ratio."
L["Help.General.preview_spells"] = "Выберите целое число предстоящих рекомендаций — от нуля (скрыто) до пяти. Предпросмотр показывает текущие результаты приоритетов, а не симуляцию будущих восстановлений или боя. Иконки изначально 64 пикселя; изменение размера масштабирует все иконки, сохраняя их квадратную форму и пропорции окна."
-- en: "Adjust the preview background and title bar opacity without fading its icons. At zero only the icons remain, and the hidden frame does not intercept blank-space clicks. Restore opacity in General to access the title bar and resize handle."
L["Help.General.preview_opacity"] = "Настроить непрозрачность фона и заголовка предпросмотра, не затемняя иконки. При нуле остаются только иконки, а скрытая рамка не перехватывает щелчки по пустому месту. Чтобы получить доступ к заголовку и уголку изменения размера, верните непрозрачность в «Общих»."
-- en: "Prevent moving the preview by its title bar or resizing it by its lower-right corner. Locking and unlocking take effect immediately and are saved without Apply. Other pending General edits remain unchanged."
L["Help.General.preview_locked"] = "Запретить перемещать предпросмотр за заголовок и менять его размер за правый нижний угол. Закрепление и открепление действуют сразу и сохраняются без нажатия «Применить». Другие ожидающие правки в «Общих» не меняются."
-- en: "Arrange preview icons horizontally (default) or vertically. Lock, Direction and Reset share one row below the opacity slider. Changing direction keeps icons square and adjusts the window ratio."
L["Help.General.preview_vertical"] = "Расположить иконки предпросмотра по горизонтали (по умолчанию) или по вертикали. «Закрепить», «Направление» и «Сбросить» находятся в одной строке под ползунком непрозрачности. Смена направления сохраняет квадратные иконки и меняет пропорции окна."
-- en: "Immediately return the preview window to the screen center and restore 64-pixel icons without Apply. Other pending settings are preserved."
L["Help.General.preview_reset"] = "Сразу вернуть окно предпросмотра в центр экрана и восстановить иконки 64 пикселя без нажатия «Применить». Другие ожидающие настройки сохраняются."
-- en: "This icon previews the selected profile effect, color, size, anchor and offsets. Previewing an effect does not save the draft or change the spell being recommended."
L["Help.General.preview"] = "Эта иконка показывает выбранные в профиле эффект, цвет, размер, точку привязки и смещения. Предпросмотр эффекта не сохраняет черновик и не меняет рекомендуемое заклинание."
-- en: "Choose the highlight used for the main recommendation and as the default for independent cooldowns. Manage available effects on the Effects page. A cooldown can override these profile settings in its action details."
L["Help.General.effect"] = "Выберите подсветку для основной рекомендации и по умолчанию для независимых восстановлений. Доступные эффекты настраиваются на странице «Эффекты». Восстановление может переопределить эти настройки профиля в сведениях о своём действии."
-- en: "Scale the highlight relative to its action icon. A value of 1 uses the icon size. Drag the slider or type its numeric value; the preview updates as you edit."
L["Help.General.magnification"] = "Масштаб подсветки относительно иконки действия. Значение 1 — размер иконки. Перетащите ползунок или введите число; предпросмотр обновляется при правке."
-- en: "Choose the highlight color and opacity. Click the color swatch to open the picker, or enter R, G, B and A values between 0 and 1. Alpha controls opacity; individual cooldowns may override this profile color."
L["Help.General.color"] = "Выберите цвет и непрозрачность подсветки. Нажмите на образец цвета, чтобы открыть палитру, или введите значения R, G, B и A от 0 до 1. Альфа задаёт непрозрачность; отдельные восстановления могут переопределять этот цвет профиля."
-- en: "Choose the point on the action icon where a texture highlight is anchored by its center. Changing Anchor resets the offsets. The preview shows the resulting placement; non-texture glows may use offsets without a texture anchor."
L["Help.General.setpoint"] = "Выберите точку на иконке действия, к которой центром привязывается текстурная подсветка. Смена точки привязки сбрасывает смещения. Предпросмотр показывает итоговое расположение; нетекстурные свечения могут использовать смещения без точки привязки текстуры."
-- en: "Vertical offset in pixels. Use Up or Down on the position control, or edit V directly. Hold Shift while using an arrow for ten pixels. Center resets both offsets and the anchor to Center."
L["Help.General.yoffs"] = "Смещение по вертикали в пикселях. Используйте «Вверх» или «Вниз» на элементе положения или измените В напрямую. Удерживайте Shift при нажатии стрелки, чтобы сдвинуть на десять пикселей. «Центрировать» сбрасывает оба смещения и точку привязки в центр."
-- en: "Horizontal offset in pixels. Use Left or Right on the position control, or edit H directly. Hold Shift while using an arrow for ten pixels. Non-texture glows interpret offsets according to their effect shape."
L["Help.General.xoffs"] = "Смещение по горизонтали в пикселях. Используйте «Влево» или «Вправо» на элементе положения или измените Г напрямую. Удерживайте Shift при нажатии стрелки, чтобы сдвинуть на десять пикселей. Нетекстурные свечения трактуют смещения в соответствии с формой эффекта."
-- en: "Choose the display name for your primary specialization. This changes its label in Rotation Master, not your character talents or specialization."
L["Help.General.spec1"] = "Выберите отображаемое название основной специализации. Меняется только подпись в Rotation Master, а не таланты или специализация персонажа."
-- en: "Choose the display name for your secondary specialization. This changes its label in Rotation Master, not your character talents or specialization."
L["Help.General.spec2"] = "Выберите отображаемое название дополнительной специализации. Меняется только подпись в Rotation Master, а не таланты или специализация персонажа."
-- en: "Choose the amount of Rotation Master chat output. Silent suppresses routine output. Default reports normal changes such as rotation switching. Debug adds runtime statistics and trigger information. Verbose includes detailed condition and highlight activity and can produce substantial output."
L["Help.General.loglevel"] = "Выберите объём вывода Rotation Master в чат. «Тихий» скрывает обычные сообщения. «По умолчанию» сообщает об обычных изменениях, например о переключении ротации. «Отладка» добавляет статистику выполнения и сведения о триггерах. «Подробный» включает подробную активность условий и подсветки и может выводить очень много текста."
-- en: "Include component timings in the periodic Debug or Verbose profiling report. Reports show measured runs, total, minimum, average and maximum in milliseconds. Timings include child work; nested scopes overlap and must not be added together. The overall scope starts after rotation preparation. This is elapsed timing, not the native addon CPU report."
L["Help.General.detailed_profiling"] = "Включать время отдельных компонентов в периодический отчёт профилирования в режимах «Отладка» и «Подробный». Отчёты показывают число измеренных запусков, общее, минимальное, среднее и максимальное время в миллисекундах. Время включает вложенную работу; вложенные области пересекаются, и их нельзя складывать. Общая область начинается после подготовки ротации. Это прошедшее время, а не встроенный отчёт ЦП аддона."
-- en: "Effects define how action-bar icons are highlighted. They are shared across characters. General settings select the main recommendation effect and cooldown default; individual cooldowns can choose another effect. Select an effect in the sidebar to inspect or edit it."
L["Help.Effects.overview"] = "Эффекты определяют, как подсвечиваются иконки на панелях команд. Они общие для всех персонажей. В общих настройках выбираются эффект основной рекомендации и эффект восстановлений по умолчанию; отдельные восстановления могут выбрать другой эффект. Выберите эффект на боковой панели, чтобы просмотреть или изменить его."
-- en: "Give the effect a name used by selectors in General and cooldown action details. New drafts can change type and fields before being named, but Apply requires a nonempty, unique name."
L["Help.Effects.name"] = "Дайте эффекту название, используемое в списках выбора в «Общих» и в сведениях о действии восстановления. В новых черновиках можно менять тип и поля до присвоения названия, но для применения нужно непустое уникальное название."
-- en: "Choose the highlight implementation. Changing type stages the new fields and resets its sequence because different sequence types store different values. Choosing the current type preserves existing values. Apply saves the change; Discard restores the saved effect."
L["Help.Effects.type"] = "Выберите реализацию подсветки. Смена типа подготавливает новые поля и сбрасывает последовательность, так как разные типы последовательностей хранят разные значения. Выбор текущего типа сохраняет существующие значения. «Применить» сохраняет изменение; «Отменить изменения» восстанавливает сохранённый эффект."
-- en: "Texture: overlay a single image from game data or an installed addon. Its color, magnification and position come from the profile or the individual cooldown."
L["Help.Effects.type.texture"] = "Текстура: наложение одного изображения из данных игры или установленного аддона. Цвет, увеличение и положение берутся из профиля или отдельного восстановления."
-- en: "Pixel: animate short lines around the action icon border. Lines, Frequency, Length and Thickness control this library glow."
L["Help.Effects.type.pixel"] = "Пиксели: анимированные короткие линии вокруг рамки иконки действия. Этим свечением библиотеки управляют «Линии», «Частота», «Длина» и «Толщина»."
-- en: "Auto Cast: animate groups of glowing particles around the action icon. Particles, Frequency and Scale control this library glow."
L["Help.Effects.type.autocast"] = "Автоприменение: анимированные группы светящихся частиц вокруг иконки действия. Этим свечением библиотеки управляют «Частицы», «Частота» и «Масштаб»."
-- en: "Glow: use the familiar Blizzard-style button glow. Frequency controls its animation rate."
L["Help.Effects.type.blizzard"] = "Свечение: привычное свечение кнопки в стиле Blizzard. «Частота» задаёт скорость анимации."
-- en: "Dazzle: keep one texture and cycle through the sequence of colors. Each sequence card contains one RGBA color."
L["Help.Effects.type.dazzle"] = "Мерцание: одна текстура с циклической сменой цветов последовательности. Каждая карточка последовательности содержит один цвет RGBA."
-- en: "Animate: cycle through the sequence of texture images. Each card selects one image and previews that selection."
L["Help.Effects.type.animate"] = "Анимация: циклическая смена изображений текстуры последовательности. Каждая карточка выбирает одно изображение и показывает его."
-- en: "Pulse: keep one texture and cycle through the sequence of magnifications. Each card selects one scale relative to the action icon."
L["Help.Effects.type.pulse"] = "Пульсация: одна текстура с циклической сменой увеличений последовательности. Каждая карточка задаёт один масштаб относительно иконки действия."
-- en: "Rotate: animate one texture through evenly spaced angles around a full circle. Steps chooses the number of angles and Reverse changes their order."
L["Help.Effects.type.rotate"] = "Вращение: анимация одной текстуры через равномерно распределённые углы полного круга. «Шаги» задаёт число углов, «Обратно» меняет их порядок."
-- en: "Custom: cycle through cards containing a texture, angle, magnification and color. Each card supplies its own settings instead of relying on one shared texture."
L["Help.Effects.type.custom"] = "Свой: циклическая смена карточек с текстурой, углом, увеличением и цветом. Каждая карточка задаёт собственные настройки вместо одной общей текстуры."
-- en: "The image beside Name and Type previews the current draft with a white color and standard size. Texture and sequence changes update the preview without saving. Actual recommendations use their profile or cooldown color, size and offsets."
L["Help.Effects.preview"] = "Изображение рядом с названием и типом показывает текущий черновик белым цветом и стандартного размера. Изменения текстуры и последовательности обновляют предпросмотр без сохранения. Настоящие рекомендации используют цвет, размер и смещения профиля или восстановления."
-- en: "For Texture, Dazzle, Pulse and Rotate, choose the image used throughout the effect. The arrow beside an image field opens the bundled overlay catalog with previews. Enter an available texture path or numeric file ID to use another image. Animate and Custom choose images in their sequence cards using the same controls. Selections update the draft and preview; Apply saves them."
L["Help.Effects.texture"] = "Для «Текстуры», «Мерцания», «Пульсации» и «Вращения» выберите изображение для всего эффекта. Стрелка рядом с полем изображения открывает каталог встроенных наложений с предпросмотром. Введите путь к доступной текстуре или числовой ID файла, чтобы использовать другое изображение. «Анимация» и «Свой» выбирают изображения в карточках последовательности теми же элементами. Выбор обновляет черновик и предпросмотр; «Применить» сохраняет его."
-- en: "Pixel effects: choose the number of animated lines around the button, from 1 to 20."
L["Help.Effects.pixel.lines"] = "Эффекты «Пиксели»: число анимированных линий вокруг кнопки, от 1 до 20."
-- en: "Pixel effects: signed cycles per second. A larger magnitude moves faster; a negative value reverses direction. Zero uses the glow library default of one cycle every four seconds."
L["Help.Effects.pixel.frequency"] = "Эффекты «Пиксели»: циклов в секунду со знаком. Чем больше модуль, тем быстрее движение; отрицательное значение меняет направление. Ноль — значение библиотеки по умолчанию: один цикл за четыре секунды."
-- en: "Pixel effects: choose line length in pixels. The glow library limits it to the smaller button dimension."
L["Help.Effects.pixel.length"] = "Эффекты «Пиксели»: длина линии в пикселях. Библиотека свечения ограничивает её меньшей стороной кнопки."
-- en: "Pixel effects: choose line thickness in pixels, from 1 to 5."
L["Help.Effects.pixel.thickness"] = "Эффекты «Пиксели»: толщина линии в пикселях, от 1 до 5."
-- en: "Auto Cast effects: choose 1 to 4 particles in each of the glow library particle groups."
L["Help.Effects.autocast.particles"] = "Эффекты «Автоприменение»: от 1 до 4 частиц в каждой группе частиц библиотеки свечения."
-- en: "Auto Cast effects: signed cycles per second. A larger magnitude moves faster; a negative value reverses direction. Zero uses the glow library default of one cycle every eight seconds."
L["Help.Effects.autocast.frequency"] = "Эффекты «Автоприменение»: циклов в секунду со знаком. Чем больше модуль, тем быстрее движение; отрицательное значение меняет направление. Ноль — значение библиотеки по умолчанию: один цикл за восемь секунд."
-- en: "Auto Cast effects: scale the particles relative to the glow library default. A value of 1 uses their normal size."
L["Help.Effects.autocast.scale"] = "Эффекты «Автоприменение»: масштаб частиц относительно значения библиотеки по умолчанию. Значение 1 — обычный размер."
-- en: "Glow effects: adjust the library animation rate. Larger positive values animate faster. Zero uses the library default rather than stopping the glow."
L["Help.Effects.blizzard.frequency"] = "Эффекты «Свечение»: скорость анимации библиотеки. Большие положительные значения ускоряют анимацию. Ноль использует значение библиотеки по умолчанию, а не останавливает свечение."
-- en: "Dazzle effects: seconds between color cards. A smaller positive interval changes colors more often; the sequence repeats after the last color."
L["Help.Effects.dazzle.frequency"] = "Эффекты «Мерцание»: секунд между карточками цветов. Меньший положительный интервал меняет цвета чаще; после последнего цвета последовательность повторяется."
-- en: "Animate effects: seconds between texture cards. A smaller positive interval changes images more often; the sequence repeats after the last image."
L["Help.Effects.animate.frequency"] = "Эффекты «Анимация»: секунд между карточками текстур. Меньший положительный интервал меняет изображения чаще; после последнего изображения последовательность повторяется."
-- en: "Pulse effects: seconds between magnification cards. A smaller positive interval changes size more often; the sequence repeats after the last size."
L["Help.Effects.pulse.frequency"] = "Эффекты «Пульсация»: секунд между карточками увеличения. Меньший положительный интервал меняет размер чаще; после последнего размера последовательность повторяется."
-- en: "Rotate effects: seconds between angle steps. A smaller positive interval rotates faster. One full cycle uses this interval multiplied by Steps."
L["Help.Effects.rotate.frequency"] = "Эффекты «Вращение»: секунд между шагами угла. Меньший положительный интервал вращает быстрее. Полный цикл занимает этот интервал, умноженный на число шагов."
-- en: "Rotate effects: choose 2 to 36 evenly spaced angles for a full turn. More steps at the same Frequency interval make a longer complete cycle."
L["Help.Effects.rotate.steps"] = "Эффекты «Вращение»: от 2 до 36 равномерно распределённых углов на полный оборот. Больше шагов при том же интервале «Частоты» — более длинный полный цикл."
-- en: "Rotate effects: reverse the order of angle steps. Changing this checkbox does not alter the texture or number of steps."
L["Help.Effects.rotate.reverse"] = "Эффекты «Вращение»: обратный порядок шагов угла. Этот флажок не меняет текстуру и число шагов."
-- en: "Custom effects: seconds between sequence cards. A smaller positive interval changes settings more often; the sequence repeats after the last card."
L["Help.Effects.custom.frequency"] = "Эффекты «Свой»: секунд между карточками последовательности. Меньший положительный интервал меняет настройки чаще; после последней карточки последовательность повторяется."
-- en: "Sequence cards play in order and repeat. Add step, on the Sequence header row, appends a card; drag Add step into a gap to insert one there. Drag a card into an insertion gap to reorder it; hold Ctrl when starting to carry it and all following cards. Up and Down move one card and are disabled at their respective ends. The red trash removes a card from the draft. Canceling a drag restores its original position."
L["Help.Effects.sequence"] = "Карточки последовательности воспроизводятся по порядку и повторяются. «Добавить шаг» в строке заголовка «Последовательность» добавляет карточку в конец; перетащите «Добавить шаг» в промежуток, чтобы вставить туда. Перетащите карточку в промежуток вставки, чтобы изменить порядок; удерживайте Ctrl в начале, чтобы перенести её вместе со всеми следующими. «Вверх» и «Вниз» сдвигают одну карточку и неактивны на соответствующих концах. Красная корзина удаляет карточку из черновика. Отмена перетаскивания возвращает исходное положение."
-- en: "Animate and Custom cards: choose a texture path or numeric file ID. The card preview shows the selected image. Custom also keeps an independent angle, magnification and color on that card."
L["Help.Effects.sequence.texture"] = "Карточки «Анимации» и «Своего»: выберите путь к текстуре или числовой ID файла. Предпросмотр карточки показывает выбранное изображение. «Свой» также хранит на этой карточке независимые угол, увеличение и цвет."
-- en: "Custom cards: set the texture angle in degrees from 0 to 359. This is the angle for this card, rather than a continuous rotation speed."
L["Help.Effects.sequence.angle"] = "Карточки «Своего»: угол текстуры в градусах от 0 до 359. Это угол для этой карточки, а не скорость непрерывного вращения."
-- en: "Pulse and Custom cards: scale the texture relative to the action icon. A value of 1 uses the icon size. Use the slider or edit its numeric value."
L["Help.Effects.sequence.magnification"] = "Карточки «Пульсации» и «Своего»: масштаб текстуры относительно иконки действия. Значение 1 — размер иконки. Используйте ползунок или введите число."
-- en: "Dazzle and Custom cards: choose an RGBA color. Click the swatch to open the picker, or edit channels between 0 and 1. Alpha controls opacity."
L["Help.Effects.sequence.color"] = "Карточки «Мерцания» и «Своего»: выберите цвет RGBA. Нажмите на образец, чтобы открыть палитру, или измените каналы от 0 до 1. Альфа задаёт непрозрачность."
-- en: "Edits and sequence changes remain in a draft. Apply saves; Discard restores the saved effect. Cancel closes a new creation draft. View Changes compares saved and unsaved values. New drafts require a unique name and valid fields before Apply. Leaving with edits offers Apply, Discard or Cancel."
L["Help.Effects.save"] = "Правки и изменения последовательности хранятся в черновике. «Применить» сохраняет; «Отменить изменения» восстанавливает сохранённый эффект. «Отмена» закрывает черновик нового. «Показать изменения» сравнивает сохранённые и несохранённые значения. Для применения нового черновика нужны уникальное название и корректные поля. При уходе с правками предлагается «Применить», «Отменить изменения» или «Отмена»."
-- en: "The red trash at the upper right deletes the selected effect after a permanent-deletion warning. Resolve pending edits first. Choose a replacement for any profile or cooldown using that effect; deletion does not silently rewrite those references."
L["Help.Effects.delete"] = "Красная корзина вверху справа удаляет выбранный эффект после предупреждения о безвозвратном удалении. Сначала разберитесь с ожидающими правками. Выберите замену для профилей и восстановлений, использующих этот эффект; удаление не переписывает эти ссылки молча."
-- en: "New, Duplicate, Import/Export and Compare are below the sidebar. Duplicate copies the selected effect into a draft. Transfers show the original name and let you create a renamed copy or replace the selection when allowed. Compare inspects differences without saving them."
L["Help.Effects.collections"] = "«Новый», «Дублировать», «Импорт/экспорт» и «Сравнить» находятся под боковой панелью. «Дублировать» копирует выбранный эффект в черновик. Перенос показывает исходное название и позволяет создать переименованную копию или, если разрешено, заменить выбранный эффект. «Сравнить» показывает различия, не сохраняя их."
-- en: "Debuffs"
L["Debuffs"] = "Отриц. эффекты"
-- en: "Resources"
L["Resources"] = "Ресурсы"
-- en: "Pet"
L["Pet"] = "Питомец"
-- en: "Logic"
L["Logic"] = "Логика"
-- en: "Environment"
L["Environment"] = "Окружение"
-- en: "Time"
L["Time"] = "Время"
-- en: "Spell Auto-Repeat Active"
L["Spell Auto-Repeat Active"] = "Автоповтор заклинания активен"
-- en: "%s {{!is|is not}} auto-repeating"
L["%s {{!is|is not}} auto-repeating"] = "%s {{!повторяется автоматически|не повторяется автоматически}}"
-- en: "Tests whether the selected spell is currently auto-repeating, such as Shoot or Auto Shot. This is different from a spell being current or queued: a queued cast alone does not satisfy this condition. Unavailable client observations remain unavailable even when negated."
L["Tests whether the selected spell is currently auto-repeating, such as Shoot or Auto Shot. This is different from a spell being current or queued: a queued cast alone does not satisfy this condition. Unavailable client observations remain unavailable even when negated."] = "Проверяет, повторяется ли сейчас выбранное заклинание автоматически, например «Выстрел» или «Автоматическая стрельба». Это не то же самое, что текущее или поставленное в очередь заклинание: одно лишь применение в очереди этому условию не удовлетворяет. Недоступные наблюдения клиента остаются недоступными даже при отрицании."
-- en: "Uses readable positions in the same instance, or player-centered range estimates when positions are unavailable. A unit counts only when its upper range bound is within Distance. Uncertain positions, range, subgroup membership or required health/mana values keep the whole condition unavailable, including under Unless. Percentage checks require a positive maximum; empty aggregates have no result."
L["Uses readable positions in the same instance, or player-centered range estimates when positions are unavailable. A unit counts only when its upper range bound is within Distance. Uncertain positions, range, subgroup membership or required health/mana values keep the whole condition unavailable, including under Unless. Percentage checks require a positive maximum; empty aggregates have no result."] = "Использует читаемые позиции в том же подземелье или, если позиции недоступны, оценки дальности относительно игрока. Юнит учитывается, только если верхняя граница его дальности не больше «Дистанции». Неопределённые позиции, дальность, принадлежность к подгруппе или нужные значения здоровья/маны делают всё условие недоступным, в том числе под «Если не». Для процентных проверок нужен положительный максимум; у пустых агрегатов нет результата."
-- en: "Paladin: Retribution (Wowhead & wowsims)"
L["Default.TBC.Paladin.Retribution.Wowhead.Name"] = "Паладин: Воздаяние (Wowhead и wowsims)"
-- en: "Melee Retribution from level 1 to 70, and the default for any Paladin no other premade fits. Opens each target with Judgement of Wisdom (low mana) or the Crusader, keeps your best seal up (Blood or Martyr, Command, then Righteousness), Crusader Strike, judges only Righteousness, Blood or Martyr (or Command on a stunned target), Exorcism on Undead and Demons, Consecration for three or more enemies with mana to spare. Hammer of Wrath is left to you (Wowhead uses it only on fleeing targets). Reminders: Sanctity, Retribution or Devotion Aura, a Blessing on yourself, a heal after the fight, Avenging Wrath. Seal twisting is a separate premade."
L["Default.TBC.Paladin.Retribution.Wowhead.Description"] = "Воздаяние в ближнем бою с 1 по 70 уровень; также используется по умолчанию для любого паладина, которому не подходит другая встроенная ротация. Начинает бой с каждой целью с Правосудия мудрости (при нехватке маны) или Правосудия воина Света, поддерживает вашу лучшую печать (Печать крови или мученика, затем повиновения, затем праведности), Удар воина Света, Правосудие только с Печатью праведности, крови или мученика (или повиновения — по оглушённой цели), Экзорцизм против нежити и демонов, Освящение при трёх и более врагах, если маны с запасом. Молот гнева остаётся за вами (Wowhead применяет его только по убегающим целям). Напоминания: Аура святости, воздаяния или благочестия, благословение на себя, исцеление после боя, Гнев карателя. Твист печатей — отдельная встроенная ротация."
-- en: "Paladin: Retribution (Icy Veins)"
L["Default.TBC.Paladin.Retribution.IcyVeins.Name"] = "Паладин: Воздаяние (Icy Veins)"
-- en: "Icy Veins' Retribution: Judgement of the Crusader once per target, Seal of Righteousness (Command only with a slow weapon, Blood or Martyr once learned), Crusader Strike, Hammer of Wrath and Judgement on cooldown, Consecration on two or more enemies, Exorcism on Undead and Demons, and Holy Shock for Holy levelers. Same reminders as the Wowhead variant."
L["Default.TBC.Paladin.Retribution.IcyVeins.Description"] = "Воздаяние по Icy Veins: Правосудие воина Света один раз на цель, Печать праведности (Печать повиновения — только с медленным оружием, Печать крови или мученика — как только изучена), Удар воина Света, Молот гнева и Правосудие по готовности, Освящение при двух и более врагах, Экзорцизм против нежити и демонов и Шок небес для паладинов, качающихся в ветке «Свет». Те же напоминания, что и в варианте Wowhead."
-- en: "Paladin: Retribution seal twisting"
L["Default.TBC.Paladin.Retribution.Twist.Name"] = "Паладин: Воздаяние, твист печатей"
-- en: "Off by default; enable it if you twist seals (level 64+, Seal of Command and Blood or Martyr). Opens with Judgement of the Crusader, then each swing puts up Seal of Command (rank 1) early and switches to Blood or Martyr in the last 0.4 seconds, Crusader Strike between twists, judges only Blood or Martyr, Exorcism and Consecration only as fillers, and rolls Blood without twisting below 12% mana. Needs a reliable swing timer; latency is not accounted for."
L["Default.TBC.Paladin.Retribution.Twist.Description"] = "По умолчанию выключена; включите её, если вы твистите печати (с 64 уровня, Печать повиновения и Печать крови или мученика). Начинает бой с Правосудия воина Света, затем перед каждым ударом оружием заранее ставит Печать повиновения (ранг 1) и в последние 0,4 секунды переключается на Печать крови или мученика; Удар воина Света между твистами, Правосудие только с Печатью крови или мученика, Экзорцизм и Освящение лишь как заполнители, а при мане ниже 12% держит Печать крови без твиста. Нужен надёжный таймер ударов оружием; задержка не учитывается."
-- en: "Paladin: Protection (Wowhead & wowsims)"
L["Default.TBC.Paladin.Protection.Wowhead.Name"] = "Паладин: Защита (Wowhead и wowsims)"
-- en: "Tanking for the Protection tree or any Paladin with Righteous Fury on. Pulls with Holy Shield, Avenger's Shield and Judgement; against a crushing target (world boss or three or more levels above you) Holy Shield comes first; then Consecration, Exorcism on Undead and Demons, Judgement, Holy Shield, Holy Wrath on undead packs, Avenger's Shield except on crushing targets. Seal of Wisdom on packs when mana is short, Righteousness otherwise. Reminders: Righteous Fury, Devotion Aura, Sanctuary (or Kings, or Wisdom), Avenging Wrath, Lay on Hands. Taunts and target swaps stay with you."
L["Default.TBC.Paladin.Protection.Wowhead.Description"] = "Танкование для ветки «Защита» или для любого паладина с включённым Праведным неистовством. Начинает бой со Щита небес, Щита мстителя и Правосудия; против цели с сокрушительными ударами (мировой босс или цель на три и более уровня выше вас) первым идёт Щит небес; затем Освящение, Экзорцизм против нежити и демонов, Правосудие, Щит небес, Гнев небес против групп нежити, Щит мстителя, кроме целей с сокрушительными ударами. Печать мудрости против групп при нехватке маны, иначе Печать праведности. Напоминания: Праведное неистовство, Аура благочестия, Благословение неприкосновенности (или королей, или мудрости), Гнев карателя, Возложение рук. Провокации и смена целей остаются за вами."
-- en: "Paladin: Protection (Icy Veins)"
L["Default.TBC.Paladin.Protection.IcyVeins.Name"] = "Паладин: Защита (Icy Veins)"
-- en: "Icy Veins' tanking: Judgement of the Crusader when nobody keeps it up, Righteousness (Wisdom on packs), Consecration as the main threat, Judgement, Holy Shield, then Avenger's Shield and Hammer of Wrath on cooldown. Same reminders as the Wowhead variant without Avenging Wrath."
L["Default.TBC.Paladin.Protection.IcyVeins.Description"] = "Танкование по Icy Veins: Правосудие воина Света, если его никто не поддерживает, Печать праведности (мудрости — против групп), Освящение как основной источник угрозы, Правосудие, Щит небес, затем Щит мстителя и Молот гнева по готовности. Те же напоминания, что и в варианте Wowhead, но без Гнева карателя."
-- en: "Paladin: Holy (Icy Veins & Wowhead)"
L["Default.TBC.Paladin.Holy.Name"] = "Паладин: Свет (Icy Veins и Wowhead)"
-- en: "Healing for a Holy Paladin in a group, on your friendly target: Lay on Hands or Holy Shock for a dying target, Cleanse (Purify before 42), Holy Shock while moving, Holy Light for heavy damage, rank-5 Holy Light to keep Light's Grace up, Flash of Light otherwise. With a hostile target it keeps Judgement of Wisdom up. Reminders: Concentration Aura, Blessing of Wisdom, Divine Illumination and Divine Favor. A soloing Holy Paladin gets a Retribution premade instead."
L["Default.TBC.Paladin.Holy.Description"] = "Лечение для паладина ветки «Свет» в группе, на дружественной цели: Возложение рук или Шок небес для умирающей цели, Очищение (до 42 уровня — Очистить), Шок небес в движении, Свет небес при сильном уроне, Свет небес 5-го ранга для поддержания Благоволения Света, в остальных случаях Вспышка Света. С враждебной целью поддерживает Правосудие мудрости. Напоминания: Аура сосредоточенности, Благословение мудрости, Божественное просветление и Божественное одобрение. Паладин ветки «Свет», играющий в одиночку, получает вместо этого встроенную ротацию «Воздаяние»."
-- en: "Paladin: Holy (Wowhead tank healing)"
L["Default.TBC.Paladin.Holy.Wowhead.Name"] = "Паладин: Свет (лечение танков, Wowhead)"
-- en: "Wowhead's raid tank healing: Holy Light whenever your target is missing a tenth of their health, Flash of Light only for small deficits, with the same emergencies, cleansing, Judgement and reminders as the blended Holy premade."
L["Default.TBC.Paladin.Holy.Wowhead.Description"] = "Лечение танков в рейде по Wowhead: Свет небес, как только цели не хватает десятой части здоровья, Вспышка Света — только при небольшой нехватке, с теми же экстренными мерами, очищением, Правосудием и напоминаниями, что и в смешанной встроенной ротации «Свет»."
-- en: "Hunter: ranged DPS (wowsims)"
L["Default.TBC.Hunter.Ranged.Wowsims.Name"] = "Охотник: урон в дальнем бою (wowsims)"
-- en: "Levels 1–70, every spec. Pulls with Hunter's Mark, Aimed Shot and Auto Shot, keeps Auto Shot running and uses melee strikes when a target reaches you. Before Steady Shot it keeps your Serpent Sting up and spends mana on Aimed, Multi and Arcane Shot only while you have plenty. From level 62: Multi-Shot when ready, Steady Shot straight after each Auto Shot, Arcane Shot to fill the gap, Serpent Sting when solo. With three or more enemies fighting you, Multi-Shot whenever it is ready. Reminds you of aspects (Viper when mana runs low, Hawk again at half mana), pet care, Kill Command, major cooldowns on elites and bosses and Silencing Shot. Pet commands, Misdirection, traps, Volley, melee weaving and Feign Death stay with you."
L["Default.TBC.Hunter.Ranged.Wowsims.Description"] = "Уровни 1–70, любая ветка талантов. Начинает бой с Метки охотника, Прицельного выстрела и Автоматической стрельбы, не прерывает Автоматическую стрельбу и использует удары ближнего боя, когда цель добирается до вас. До изучения Верного выстрела поддерживает Укус змеи и тратит ману на Прицельный, Чародейский выстрел и Залп только при большом запасе маны. С 62 уровня: Залп по готовности, Верный выстрел сразу после каждого автоматического выстрела, Чародейский выстрел, чтобы заполнить паузу, Укус змеи в одиночной игре. Если с вами сражаются три и более врага — Залп всякий раз, когда он готов. Напоминает о аспектах (Дух гадюки при нехватке маны, снова Дух ястреба на половине маны), уходе за питомцем, Команде «Взять!», крупных способностях с восстановлением против элитных противников и боссов и о Глушащем выстреле. Команды питомцу, Перенаправление, ловушки, Град стрел, вплетение ударов ближнего боя и Притвориться мертвым остаются за вами."
-- en: "Hunter: ranged DPS (Wowhead)"
L["Default.TBC.Hunter.Ranged.Wowhead.Name"] = "Охотник: урон в дальнем бою (Wowhead)"
-- en: "Levels 1–70, every spec, following Wowhead's raid advice. Same pull, melee, leveling shots, multi-target Multi-Shot and reminders as the wowsims version, but once Steady Shot is learned it only offers Multi-Shot and Steady Shot after each Auto Shot: no Arcane Shot filler (except while moving), no Serpent Sting and no Aspect of the Viper reminder. Pet commands, Misdirection, traps, Volley, melee weaving and Feign Death stay with you."
L["Default.TBC.Hunter.Ranged.Wowhead.Description"] = "Уровни 1–70, любая ветка талантов, по рейдовым советам Wowhead. Те же начало боя, ближний бой, выстрелы для прокачки, Залп против нескольких целей и напоминания, что и в версии wowsims, но после изучения Верного выстрела после каждого автоматического выстрела предлагает только Залп и Верный выстрел: без Чародейского выстрела как заполнителя (кроме как в движении), без Укуса змеи и без напоминания о Духе гадюки. Команды питомцу, Перенаправление, ловушки, Град стрел, вплетение ударов ближнего боя и Притвориться мертвым остаются за вами."
-- en: "Rogue: melee DPS (wowsims)"
L["Default.TBC.Rogue.DPS.Wowsims.Name"] = "Разбойник: урон в ближнем бою (wowsims)"
-- en: "Levels 1–70, every spec. From stealth: Premeditation, then Cheap Shot solo or Garrote in a group, otherwise Ambush. In combat: Riposte, Slice and Dice from two combo points (renewed in its last two seconds), Eviscerate on a target about to die, and at five points Rupture when it will last (not while Blade Flurry cleaves), otherwise Eviscerate. Builds with Mutilate or Backstab when the target is not attacking you, otherwise Hemorrhage or Sinister Strike. Reminds you of missing poisons, Kick, Blade Flurry and Adrenaline Rush, Cold Blood and Evasion. Expose Armor, Kidney Shot, Feint, Vanish and positioning stay with you."
L["Default.TBC.Rogue.DPS.Wowsims.Description"] = "Уровни 1–70, любая ветка талантов. Из незаметности: Умысел, затем Подлый трюк в одиночку или Гаррота в группе, иначе Внезапный удар. В бою: Ответный удар, Мясорубка от двух очков серии (обновляется в последние две секунды), Потрошение по цели, которая вот-вот умрёт, а на пяти очках — Рваная рана, если она успеет отработать (но не во время Шквала клинков), иначе Потрошение. Набирает очки Расправой или Ударом в спину, когда цель не атакует вас, иначе Кровоизлиянием или Коварным ударом. Напоминает об отсутствующих ядах, Пинке, Шквале клинков и Выбросе адреналина, Хладнокровии и Ускользании. Ослабление доспеха, Удар по почкам, Ложный выпад, Исчезновение и позиционирование остаются за вами."
-- en: "Rogue: melee DPS (Wowhead)"
L["Default.TBC.Rogue.DPS.Wowhead.Name"] = "Разбойник: урон в ближнем бою (Wowhead)"
-- en: "Levels 1–70, every spec, following Wowhead. Same stealth openers, builders and reminders as the wowsims version, but Slice and Dice starts from one combo point and every five-point finisher is Eviscerate: no Rupture. Expose Armor, Kidney Shot, Feint, Vanish and positioning stay with you."
L["Default.TBC.Rogue.DPS.Wowhead.Description"] = "Уровни 1–70, любая ветка талантов, по Wowhead. Те же атаки из незаметности, приёмы набора очков и напоминания, что и в версии wowsims, но Мясорубка ставится уже с одного очка серии, а каждый добивающий приём на пяти очках — Потрошение: без Рваной раны. Ослабление доспеха, Удар по почкам, Ложный выпад, Исчезновение и позиционирование остаются за вами."
-- en: "Druid: Balance"
L["Default.TBC.Druid.Balance.Name"] = "Друид: Баланс"
-- en: "Caster Balance from level 1 to 70, and the default for any Druid no other premade fits. Pulls with Starfire (Wrath before 20), Insect Swarm and Moonfire while moving, Faerie Fire in a group, Hurricane for three or more enemies, Moonfire when it has run out and you have 30% mana, Starfire on Nature's Grace, Wrath against a target in melee, then Starfire (Wrath before it is learned). No advice in Cat, Bear or travel forms. Reminders: Mark of the Wild, Thorns while solo, Omen of Clarity, Moonkin Form, Force of Nature on a long fight, Innervate when low."
L["Default.TBC.Druid.Balance.Description"] = "Заклинатель ветки «Баланс» с 1 по 70 уровень; также используется по умолчанию для любого друида, которому не подходит другая встроенная ротация. Начинает бой Звездным огнем (до 20 уровня — Гневом), Рой насекомых и Лунный огонь в движении, Волшебный огонь в группе, Гроза при трёх и более врагах, Лунный огонь, когда он истёк и у вас есть 30% маны, Звездный огонь при Благоволении природы, Гнев по цели в ближнем бою, затем Звездный огонь (Гнев, пока он не изучен). В облике кошки, медведя и походном облике советов нет. Напоминания: Знак дикой природы, Шипы в одиночной игре, Знамение ясности, Облик лунного совуха, Сила Природы в долгом бою, Озарение при нехватке маны."
-- en: "Druid: Feral (Icy Veins, Warcraft Tavern & wowsims)"
L["Default.TBC.Druid.Feral.IcyVeins.Name"] = "Друид: Сила зверя (Icy Veins, Warcraft Tavern и wowsims)"
-- en: "Cat and bear for the Feral tree, following your form. Cat: stealth opener (Pounce, Ravage or Shred), Faerie Fire (Feral), Rip at four combo points on a target that lives, Ferocious Bite between Rips without Clearcasting, Mangle kept up, Shred from behind or Mangle/Claw when the target is on you. Bear: Faerie Fire, Lacerate saved before it drops, Demoralizing Roar unless a warrior's Shout is up, Swipe for packs, Mangle, five Lacerates, Swipe. In caster form it suggests Cat (or Bear) Form. Reminders: Mark, Thorns, Omen, Maul with spare rage, Tiger's Fury before a pull, Frenzied Regeneration. Powershifting is an optional step that starts off (it needs a powershift macro)."
L["Default.TBC.Druid.Feral.IcyVeins.Description"] = "Кошка и медведь для ветки «Сила зверя» в зависимости от вашего облика. Кошка: атака из незаметности (Наскок, Накинуться или Полоснуть), Волшебный огонь (сила зверя), «Разорвать» на четырёх очках серии по цели, которая проживёт достаточно долго, Свирепый укус между «Разорвать» без Ясности мысли, поддержание Увечья, Полоснуть из-за спины или Увечье/Когти, когда цель бьёт вас. Медведь: Волшебный огонь, Растерзать обновляется до того, как спадёт, Устрашающий рев, если не висит крик воина, Размах против групп, Увечье, пять наложений Растерзать, Размах. В облике заклинателя предлагает Облик кошки (или медведя). Напоминания: Знак, Шипы, Знамение, Трепка при лишней ярости, Тигриное неистовство перед боем, Неистовое восстановление. Смена облика ради энергии (powershifting) — необязательный шаг, по умолчанию выключенный (нужен макрос для powershift)."
-- en: "Druid: Feral (Wowhead)"
L["Default.TBC.Druid.Feral.Wowhead.Name"] = "Друид: Сила зверя (Wowhead)"
-- en: "Wowhead's Feral: Rip whenever it is down at four combo points and Ferocious Bite only on a target about to die (no bite-weaving); bears spend free global cooldowns on Lacerate before Swipe. Innervate when a cat runs low on mana. Otherwise the same as the Icy Veins variant."
L["Default.TBC.Druid.Feral.Wowhead.Description"] = "Сила зверя по Wowhead: «Разорвать» всякий раз, когда он спал, на четырёх очках серии, а Свирепый укус — только по цели, которая вот-вот умрёт (без вплетения укусов); медведь тратит свободные ГКД на Растерзать перед Размахом. Озарение, когда у кошки кончается мана. В остальном — как вариант Icy Veins."
-- en: "Druid: Restoration"
L["Default.TBC.Druid.Restoration.Name"] = "Друид: Исцеление"
-- en: "Healing for the Restoration tree on your friendly target (or yourself): Healing Touch after Nature's Swiftness, Swiftmend a dying target that has your Rejuvenation or Regrowth, three rolling Lifeblooms in combat, Rejuvenation and Regrowth when missing, then Regrowth in Tree of Life or Healing Touch outside it. A hostile target gets Moonfire and Wrath for soloing. Reminders: Mark, Omen, Tree of Life, Nature's Swiftness, Tranquility, Innervate and Rebirth. Choosing whom to heal and downranking stay with you."
L["Default.TBC.Druid.Restoration.Description"] = "Лечение для ветки «Исцеление» на дружественной цели (или на себе): Целительное прикосновение после Природной стремительности, Быстрое восстановление на умирающую цель с вашим Омоложением или Восстановлением, три постоянно обновляемых наложения Жизнецвета в бою, Омоложение и Восстановление, если их нет, затем Восстановление в облике Древа жизни или Целительное прикосновение вне его. Против враждебной цели — Лунный огонь и Гнев для одиночной игры. Напоминания: Знак, Знамение, Древо жизни, Природная стремительность, Спокойствие, Озарение и Возрождение. Кого лечить и понижение ранга заклинаний остаются за вами."
-- en: "Warrior: melee DPS (wowsims)"
L["Default.TBC.Warrior.DPS.Wowsims.Name"] = "Воин: урон в ближнем бою (wowsims)"
-- en: "Levels 1–70, Arms or Fury. Charges to pull, then Victory Rush, Intercept, Rampage, and Whirlwind when two or more enemies fight you (Thunder Clap before it is learned). With Bloodthirst or Mortal Strike: that strike, Whirlwind with rage to spare, Execute, Overpower. Before them: Whirlwind, Execute, Overpower, Rend. Spare rage goes to Devastate or Sunder Armor, then Hamstring. Reminds you of Battle Shout, Bloodrage, Heroic Strike or Cleave as rage dumps, Sweeping Strikes, Death Wish, Recklessness and interrupts. Slam timing, stance dancing and Berserker Rage stay with you."
L["Default.TBC.Warrior.DPS.Wowsims.Description"] = "Уровни 1–70, «Оружие» или «Неистовство». Начинает бой Рывком, затем Победный раж, Перехват, Буйство и Вихрь, когда с вами сражаются два и более врага (до его изучения — Удар грома). С Кровожадностью или Смертельным ударом: этот удар, Вихрь при лишней ярости, Казнь, Превосходство. До их изучения: Вихрь, Казнь, Превосходство, Кровопускание. Лишняя ярость уходит на Разрушение или Раскол брони, затем на Подрезать сухожилия. Напоминает о Боевом крике, Кровавой ярости, Ударе героя или Рассекающем ударе для сброса ярости, Размашистых ударах, Инстинкте смерти, Безрассудстве и прерываниях. Тайминг Сокрушения, смена стоек и Ярость берсерка остаются за вами."
-- en: "Warrior: melee DPS (Icy Veins)"
L["Default.TBC.Warrior.DPS.IcyVeins.Name"] = "Воин: урон в ближнем бою (Icy Veins)"
-- en: "Levels 1–70, Arms or Fury, following Icy Veins. Same pull, reminders and leveling steps as the wowsims version, but with Mortal Strike Execute comes first, with Bloodthirst Execute comes right after it, Whirlwind follows without holding rage, and Hamstring only near full rage. Slam timing, stance dancing and Berserker Rage stay with you."
L["Default.TBC.Warrior.DPS.IcyVeins.Description"] = "Уровни 1–70, «Оружие» или «Неистовство», по Icy Veins. Те же начало боя, напоминания и шаги для прокачки, что и в версии wowsims, но со Смертельным ударом первой идёт Казнь, с Кровожадностью Казнь идёт сразу после неё, Вихрь следует без накопления ярости, а Подрезать сухожилия — только при почти полной ярости. Тайминг Сокрушения, смена стоек и Ярость берсерка остаются за вами."
-- en: "Warrior: tank (Wowhead)"
L["Default.TBC.Warrior.Protection.Wowhead.Name"] = "Воин: танк (Wowhead)"
-- en: "Levels 10–70, chosen while you are in Defensive Stance. Shield Slam, Revenge, Thunder Clap and Demoralizing Shout kept up on elites and bosses, then Devastate or Sunder Armor. On packs: Thunder Clap and Demoralizing Shout first. Reminds you of Shield Block against bosses and higher-level enemies, Heroic Strike or Cleave, Battle Shout, Bloodrage, Shield Bash and emergency Last Stand and Shield Wall. Taunting and other utility stay with you."
L["Default.TBC.Warrior.Protection.Wowhead.Description"] = "Уровни 10–70; выбирается, пока вы в Оборонительной стойке. Сокрушение щитом, Реванш, Удар грома и Деморализующий крик поддерживаются на элитных противниках и боссах, затем Разрушение или Раскол брони. Против групп: сначала Удар грома и Деморализующий крик. Напоминает о Блоке щитом против боссов и врагов более высокого уровня, Ударе героя или Рассекающем ударе, Боевом крике, Кровавой ярости, Ударе щитом, а в экстренных случаях — о «Ни шагу назад» и Глухой обороне. Провокация и прочие вспомогательные способности остаются за вами."
-- en: "Warrior: tank (Icy Veins)"
L["Default.TBC.Warrior.Protection.IcyVeins.Name"] = "Воин: танк (Icy Veins)"
-- en: "Levels 10–70, chosen while you are in Defensive Stance, following Icy Veins. Shield Slam, Revenge, then Devastate or Sunder Armor, with Rend at the start of a fight until Shield Slam is learned. On packs: Thunder Clap, and Demoralizing Shout against elites. Shield Block is reminded whenever your target is attacking you. Taunting and other utility stay with you."
L["Default.TBC.Warrior.Protection.IcyVeins.Description"] = "Уровни 10–70; выбирается, пока вы в Оборонительной стойке, по Icy Veins. Сокрушение щитом, Реванш, затем Разрушение или Раскол брони, а в начале боя — Кровопускание, пока не изучено Сокрушение щитом. Против групп: Удар грома, а против элитных противников — Деморализующий крик. О Блоке щитом напоминает всякий раз, когда цель атакует вас. Провокация и прочие вспомогательные способности остаются за вами."
-- en: "Priest: damage (Icy Veins)"
L["Default.TBC.Priest.DpsIcyVeins.Name"] = "Жрец: урон (Icy Veins)"
-- en: "Damage from level 1 to 70, used whenever the healer premade does not apply. Smite and wand early, then Mind Blast, Shadow Word: Pain, Mind Flay, Shadowform, Vampiric Touch and Shadow Word: Death as you learn them; DoTs before Mind Blast; a dying target is wanded when solo. Holy and Discipline questers get Holy Fire and Smite. Reminders: Inner Fire, Fortitude, racial buffs, Inner Focus, Shadowfiend. Shields, healing and Mind Flay clipping stay with you."
L["Default.TBC.Priest.DpsIcyVeins.Description"] = "Урон с 1 по 70 уровень; используется всегда, когда не подходит встроенная ротация лекаря. Сначала Кара и жезл, затем Взрыв разума, Слово Тьмы: Боль, Пытка разума, Облик Тьмы, Прикосновение вампира и Слово Тьмы: Смерть по мере изучения; DoT — раньше Взрыва разума; в одиночной игре умирающую цель добивает жезл. Жрецы веток «Свет» и «Послушание», выполняющие задания, получают Священный огонь и Кару. Напоминания: Внутренний огонь, Стойкость, расовые положительные эффекты, Внутреннее сосредоточение, Исчадие Тьмы. Щиты, лечение и досрочное прерывание Пытки разума остаются за вами."
-- en: "Priest: damage (Wowhead)"
L["Default.TBC.Priest.DpsWowhead.Name"] = "Жрец: урон (Wowhead)"
-- en: "Damage after Wowhead's guides: Mind Blast opens and goes before DoT refreshes, Vampiric Embrace only when your health drops, and a dying target gets spells instead of the wand. Otherwise the same as the Icy Veins damage premade. Pick it in the rotation list to use it."
L["Default.TBC.Priest.DpsWowhead.Description"] = "Урон по руководствам Wowhead: Взрыв разума начинает бой и идёт раньше обновления DoT, Объятия вампира — только когда падает ваше здоровье, а умирающую цель добивают заклинаниями, а не жезлом. В остальном — как встроенная ротация урона Icy Veins. Чтобы использовать её, выберите её в списке ротаций."
-- en: "Priest: healer (Wowhead)"
L["Default.TBC.Priest.HealerWowhead.Name"] = "Жрец: лекарь (Wowhead)"
-- en: "Healing in a group when Holy or Discipline is your main talent tree. It advises on the friendly unit you target; you choose whom to heal. Prayer of Mending before pulls and whenever ready, Renew, Power Word: Shield in emergencies, dispels, Circle of Healing or Prayer of Healing for group damage, Binding, Flash and Greater Heal, and Greater Heal rank 1 as a cheap top-up. With an enemy targeted it offers light damage."
L["Default.TBC.Priest.HealerWowhead.Description"] = "Лечение в группе, когда «Свет» или «Послушание» — ваша основная ветка талантов. Советы даются для дружественного юнита в цели; кого лечить, выбираете вы. Молитва восстановления перед боем и всякий раз по готовности, Обновление, Слово силы: Щит в экстренных случаях, рассеивание, Круг исцеления или Молитва исцеления при уроне по группе, Связующее, Быстрое и Сильное исцеление, а также Сильное исцеление 1-го ранга как дешёвая подпитка. Если в цели враг, предлагает немного урона."
-- en: "Priest: healer (Icy Veins)"
L["Default.TBC.Priest.HealerIcyVeins.Name"] = "Жрец: лекарь (Icy Veins)"
-- en: "Healing after Icy Veins' order: Shield, dispels, Binding Heal, Renew, Flash Heal, Greater Heal (any rank), group heals, and Prayer of Mending last. You choose whom to heal. Pick it in the rotation list to use it."
L["Default.TBC.Priest.HealerIcyVeins.Description"] = "Лечение в порядке Icy Veins: щит, рассеивание, Связующее исцеление, Обновление, Быстрое исцеление, Сильное исцеление (любого ранга), групповое лечение и последней — Молитва восстановления. Кого лечить, выбираете вы. Чтобы использовать её, выберите её в списке ротаций."
-- en: "Warlock: all trees (Icy Veins)"
L["Default.TBC.Warlock.DpsIcyVeins.Name"] = "Чернокнижник: все ветки (Icy Veins)"
-- en: "Every talent tree from level 1 to 70. Curse, then Unstable Affliction, Immolate, Corruption and Siphon Life as learned, Shadow Bolt or Incinerate; Nightfall and Backlash procs first; Seed, Hellfire and Shadowfury for three or more enemies. Solo it drains when hurt, Life Taps, wands, and uses Drain Soul or a finisher on a dying target. Reminders: Fel Armor, Demon Armor or Demon Skin, your demon, sacrifice, Soul Link, Amplify Curse and Soulshatter. Fears and other curses stay with you."
L["Default.TBC.Warlock.DpsIcyVeins.Description"] = "Все ветки талантов с 1 по 70 уровень. Проклятие, затем Нестабильное колдовство, Жертвенный огонь, Порча и Вытягивание жизни по мере изучения, Стрела Тьмы или Испепеление; сначала срабатывания Сумерек и Отдачи; Семя порчи, Адское пламя и Неистовство Тьмы при трёх и более врагах. В одиночной игре похищает жизнь, когда вы ранены, использует Жизнеотвод, жезл, а на умирающей цели — Похищение души или добивающее заклинание. Напоминания: Доспех Скверны, Демонический доспех или Шкура демона, ваш демон, жертвоприношение, Связка души, Усиление проклятия и Раскол души. Страх и прочие проклятия остаются за вами."
-- en: "Warlock: drain-tank (Wowhead)"
L["Default.TBC.Warlock.DpsWowhead.Name"] = "Чернокнижник: дрейн-танк (Wowhead)"
-- en: "Warlock after Wowhead's guides. Solo it drain-tanks: Drain Life is the filler once your DoTs are up and Immolate and Siphon Life are kept for elite mobs. In a group Immolate always goes on, after Corruption and Siphon Life. Otherwise the same as the Icy Veins Warlock premade. Pick it in the rotation list to use it."
L["Default.TBC.Warlock.DpsWowhead.Description"] = "Чернокнижник по руководствам Wowhead. В одиночной игре танкует похищением (дрейн-танк): Похищение жизни становится основным заклинанием, как только ваши DoT наложены, а Жертвенный огонь и Вытягивание жизни приберегаются для элитных противников. В группе Жертвенный огонь накладывается всегда, после Порчи и Вытягивания жизни. В остальном — как встроенная ротация чернокнижника Icy Veins. Чтобы использовать её, выберите её в списке ротаций."
-- en: "Count enemies when selected, or non-enemies when cleared."
L["Count enemies when selected, or non-enemies when cleared."] = "Если отмечено — считать противников, если нет — не-противников."
-- en: "The number of observed units proven within Distance of you."
L["The number of observed units proven within Distance of you."] = "Число наблюдаемых юнитов, достоверно находящихся в пределах «Дистанции» от вас."
-- en: "Counts the addon's observed unit snapshot, including nameplates and tracked unit aliases, rather than every nearby unit. A unit counts only when its upper range bound is within Distance; uncertain membership or unreadable identity, hostility, range or nameplate settings makes the whole count unavailable, including under Unless. Known vanished or reused unit tokens are excluded. Distance cannot exceed the current nameplate distance setting; that setting does not guarantee a complete scan."
L["Counts the addon's observed unit snapshot, including nameplates and tracked unit aliases, rather than every nearby unit. A unit counts only when its upper range bound is within Distance; uncertain membership or unreadable identity, hostility, range or nameplate settings makes the whole count unavailable, including under Unless. Known vanished or reused unit tokens are excluded. Distance cannot exceed the current nameplate distance setting; that setting does not guarantee a complete scan."] = "Считает снимок наблюдаемых аддоном юнитов, включая индикаторы здоровья и отслеживаемые псевдонимы юнитов, а не все юниты поблизости. Юнит учитывается, только если верхняя граница его дальности не больше «Дистанции»; неопределённая принадлежность или нечитаемые идентичность, враждебность, дальность или настройки индикаторов делают весь подсчёт недоступным, в том числе под «Если не». Известные исчезнувшие или переиспользованные токены юнитов исключаются. «Дистанция» не может превышать текущую настройку дальности индикаторов здоровья; эта настройка не гарантирует полного охвата."
-- en: "Selecting a sidebar row only inspects that profile. Activate profile switches the live profile immediately, including its rotations and settings. The active profile shows Active profile instead. This operation does not wait for page Apply."
L["Help.Profiles.activate"] = "Выбор строки на боковой панели только показывает этот профиль. «Активировать профиль» сразу переключает действующий профиль вместе с его ротациями и настройками. Для активного профиля вместо этого показано «Активный профиль». Эта операция не ждёт нажатия «Применить» на странице."
-- en: "Choose a source to replace the active profile after confirmation. This copies settings and rotations into the active profile, even when the sidebar is inspecting a different profile. It does not switch to the source or rename the active profile. Cancel at the confirmation preserves the current profile."
L["Help.Profiles.copy"] = "Выберите источник, чтобы после подтверждения заменить им активный профиль. Настройки и ротации копируются в активный профиль, даже если на боковой панели выбран другой профиль. Переключения на источник и переименования активного профиля не происходит. «Отмена» в подтверждении сохраняет текущий профиль."
-- en: "Reset current profile replaces the active profile with its defaults after confirmation. Custom rotations and settings in it are replaced. The control is disabled while inspecting another profile. Reset is immediate after confirmation; there is no later page Apply to undo it."
L["Help.Profiles.reset"] = "«Сбросить текущий профиль» после подтверждения заменяет активный профиль значениями по умолчанию. Свои ротации и настройки в нём заменяются. Элемент неактивен, пока просматривается другой профиль. Сброс выполняется сразу после подтверждения; последующего «Применить» на странице, которым его можно было бы отменить, нет."
-- en: "The red trash can permanently removes the selected inactive profile after confirmation. The active profile and Default cannot be deleted here. Selecting another profile does not delete or activate it."
L["Help.Profiles.delete"] = "Красная корзина после подтверждения безвозвратно удаляет выбранный неактивный профиль. Активный профиль и Default здесь удалить нельзя. Выбор другого профиля не удаляет и не активирует его."
-- en: "New and Duplicate open a named draft. Use a nonblank, unused name of at most 50 characters. Apply creates the profile; Cancel abandons creation. Creating a profile leaves the previously active profile active, so use Activate profile when you want to switch to the new copy."
L["Help.Profiles.new_name"] = "«Новый» и «Дублировать» открывают именованный черновик. Используйте непустое, не занятое название длиной не более 50 символов. «Применить» создаёт профиль; «Отмена» отменяет создание. После создания активным остаётся прежний профиль, поэтому, чтобы переключиться на новую копию, используйте «Активировать профиль»."
-- en: "The buttons below the list create a new profile, duplicate the selected profile, transfer profiles or compare saved settings. Search narrows the list without activating a profile. Import/Export shows the original name and lets you replace the selection or create a renamed copy. Importing a new profile opens a creation draft; Apply saves it. Replacing a selected profile happens when you confirm the import, and replacing the active profile updates its runtime settings. Compare does not apply changes."
L["Help.Profiles.collections"] = "Кнопки под списком создают новый профиль, дублируют выбранный, переносят профили или сравнивают сохранённые настройки. Поиск сужает список, не активируя профиль. «Импорт/экспорт» показывает исходное название и позволяет заменить выбранный профиль или создать переименованную копию. Импорт нового профиля открывает черновик создания; «Применить» сохраняет его. Замена выбранного профиля происходит при подтверждении импорта, а замена активного профиля обновляет его действующие настройки. «Сравнить» изменения не применяет."
-- en: "Status pills show Not loaded, Supported, Disabled, Enabled or Selected. Click Enabled to Select or Disable. Disabling Selected chooses the sole enabled available editor, offers a choice when several exist, or leaves none selected. Enabling an editor when none is selected selects it automatically. Native is always available; its Syntax highlighting option is independent of editor selection. With no enabled editor, emergency plain text remains usable. Apply saves preferences for the next source-editor opening; Discard keeps saved settings. An open editor keeps its current provider."
L["Help.Integrations.lua_editor"] = "Метки состояния: «Не загружен», «Поддерживается», «Отключён», «Включён» или «Выбран». Нажмите на «Включён», чтобы выбрать или отключить. Отключение выбранного выбирает единственный включённый доступный редактор, предлагает выбор, если их несколько, или оставляет редактор невыбранным. Включение редактора, когда ни один не выбран, выбирает его автоматически. Встроенный редактор доступен всегда; его параметр подсветки синтаксиса не зависит от выбора редактора. Если ни один редактор не включён, остаётся аварийный простой текст. «Применить» сохраняет настройки для следующего открытия редактора исходного кода; «Отменить изменения» сохраняет прежние настройки. Открытый редактор сохраняет текущего поставщика."
-- en: "Show line numbers controls the gutter in every condition and function code editor. It defaults to enabled. Apply saves the preference and updates open code panes; Discard keeps the saved setting. It does not change the Lua source or its line breaks."
L["Help.Integrations.lua_line_numbers"] = "«Показывать номера строк» управляет полем номеров во всех редакторах кода условий и функций. По умолчанию включено. «Применить» сохраняет настройку и обновляет открытые панели кода; «Отменить изменения» сохраняет прежнюю. Исходный код Lua и его переносы строк не меняются."
-- en: "Addon names open copyable official release and source links across available providers. Edition filtering follows declared support for the matching addon identity; unknown compatibility remains visible. An older release date alone does not prove incompatibility. Listed game-edition support describes publisher release evidence, not certification of the integration on your client. Some integrations have only historical or unverified releases. Not loaded means unavailable to RM; Supported identifies an available integration without an enable switch. Bundled libraries are excluded. Rotation Master does not install or enable other addons."
L["Help.Integrations.optional_addons"] = "Названия аддонов открывают копируемые ссылки на официальные выпуски и исходный код у доступных площадок. Фильтр по изданию следует заявленной поддержке соответствующего аддона; неизвестная совместимость остаётся видимой. Более старая дата выпуска сама по себе не доказывает несовместимость. Указанная поддержка изданий игры отражает данные издателя о выпусках, а не сертификацию интеграции на вашем клиенте. У некоторых интеграций есть только исторические или непроверенные выпуски. «Не загружен» означает, что для RM он недоступен; «Поддерживается» обозначает доступную интеграцию без переключателя. Встроенные библиотеки не учитываются. Rotation Master не устанавливает и не включает другие аддоны."
-- en: "Apply / Discard"
L["Apply / Discard"] = "Применить / Отменить изменения"
-- en: "Edits stay in a draft until Apply. Discard abandons pending changes. Leaving with changes offers Apply, Discard or Cancel; Cancel keeps the page and draft open. Effect previews do not save changes. Action-bar binding operations are explicit and immediate."
L["Edits stay in a draft until Apply. Discard abandons pending changes. Leaving with changes offers Apply, Discard or Cancel; Cancel keeps the page and draft open. Effect previews do not save changes. Action-bar binding operations are explicit and immediate."] = "Правки хранятся в черновике до нажатия «Применить». «Отменить изменения» отбрасывает ожидающие изменения. При уходе с изменениями предлагается «Применить», «Отменить изменения» или «Отмена»; «Отмена» оставляет страницу и черновик открытыми. Предпросмотр эффектов не сохраняет изменения. Операции привязки к панелям команд явные и выполняются сразу."
-- en: "Diagram / List changes only the rotation view; General settings choose the default. Diagram has floating minus, percentage and plus controls at the bottom right. Scroll to zoom from 25% to 200%; click the percentage or middle-click to reset to 100%. Drag empty diagram space to pan. List uses normal scrollbars with touching cards and boxed branch arms, False before True. Cooldowns use a separate scrolling grid. Dragging cards reorders them in every view. Valid rotation bodies can contain up to 2,000 total steps; large workspaces reuse nearby card controls as you navigate. Folded branches intentionally hide their children."
L["Diagram / List changes only the rotation view; General settings choose the default. Diagram has floating minus, percentage and plus controls at the bottom right. Scroll to zoom from 25% to 200%; click the percentage or middle-click to reset to 100%. Drag empty diagram space to pan. List uses normal scrollbars with touching cards and boxed branch arms, False before True. Cooldowns use a separate scrolling grid. Dragging cards reorders them in every view. Valid rotation bodies can contain up to 2,000 total steps; large workspaces reuse nearby card controls as you navigate. Folded branches intentionally hide their children."] = "«Схема / Список» меняет только вид ротации; вид по умолчанию задаётся в общих настройках. На схеме внизу справа есть плавающие кнопки «минус», процент и «плюс». Прокрутка меняет масштаб от 25% до 200%; нажатие на процент или средней кнопкой мыши сбрасывает его до 100%. Перетаскивайте пустое место схемы, чтобы сдвигать вид. В списке обычные полосы прокрутки, карточки идут вплотную, а плечи ветвей обведены рамками: «Ложь» перед «Истиной». Восстановления используют отдельную прокручиваемую сетку. Перетаскивание карточек меняет их порядок в любом виде. Корректная ротация может содержать до 2000 шагов; в больших рабочих областях элементы карточек переиспользуются по мере навигации. Свёрнутые ветви намеренно скрывают вложенные элементы."
-- en: "New / Duplicate / Import / Compare"
L["New / Duplicate / Import / Compare"] = "Новый / Дублировать / Импорт / Сравнить"
-- en: "Choose a category and search for a condition. Hidden removes it from pickers without deleting its definition. Switch Condition controls its availability for automatic rotation switching. Move To stages a category destination; its Apply button confirms the move. The assigned category opens category management. Sidebar arrows and dragging order entries. Page Apply saves the draft; Discard abandons edits to a saved entry. Custom conditions can be edited, duplicated or deleted."
L["Choose a category and search for a condition. Hidden removes it from pickers without deleting its definition. Switch Condition controls its availability for automatic rotation switching. Move To stages a category destination; its Apply button confirms the move. The assigned category opens category management. Sidebar arrows and dragging order entries. Page Apply saves the draft; Discard abandons edits to a saved entry. Custom conditions can be edited, duplicated or deleted."] = "Выберите категорию и найдите условие. «Скрыто» убирает его из списков выбора, не удаляя определение. «Условие переключения» определяет его доступность для автопереключения ротаций. «Переместить в» подготавливает категорию назначения; кнопка «Применить» рядом подтверждает перемещение. Назначенная категория открывает управление категориями. Стрелки и перетаскивание на боковой панели упорядочивают элементы. «Применить» страницы сохраняет черновик; «Отменить изменения» отбрасывает правки сохранённой записи. Пользовательские условия можно изменять, дублировать и удалять."
-- en: "Select an effect to edit its name, type and type-specific settings. The icon previews it live. Sequence sections edit animation, color, pulse or custom frames in order. Duplicate creates an independent effect. Drag a sequence card surface to reorder it; fields remain editable. New effects can be configured before naming. Apply saves the draft; Discard abandons edits to a saved entry. Import stages a validated replacement."
L["Select an effect to edit its name, type and type-specific settings. The icon previews it live. Sequence sections edit animation, color, pulse or custom frames in order. Duplicate creates an independent effect. Drag a sequence card surface to reorder it; fields remain editable. New effects can be configured before naming. Apply saves the draft; Discard abandons edits to a saved entry. Import stages a validated replacement."] = "Выберите эффект, чтобы изменить его название, тип и настройки, зависящие от типа. Иконка показывает его вживую. Разделы последовательности по порядку настраивают анимацию, цвет, пульсацию или свои кадры. «Дублировать» создаёт независимый эффект. Перетаскивайте поверхность карточки последовательности, чтобы изменить порядок; поля остаются редактируемыми. Новые эффекты можно настроить до присвоения названия. «Применить» сохраняет черновик; «Отменить изменения» отбрасывает правки сохранённой записи. Импорт подготавливает проверенную замену."
-- en: "Choose an item set and edit its priority list. Global shares the set across profiles. Move arrows change item priority. Bind item set picks up an available item for placement on an action bar; The binding pill removes matching bound bar actions when unbinding, outside combat. Reset restores a packaged set. Search or drag items into reference fields. Apply saves settings; Discard abandons edits to a saved entry. Binding changes are explicit action-bar operations."
L["Choose an item set and edit its priority list. Global shares the set across profiles. Move arrows change item priority. Bind item set picks up an available item for placement on an action bar; The binding pill removes matching bound bar actions when unbinding, outside combat. Reset restores a packaged set. Search or drag items into reference fields. Apply saves settings; Discard abandons edits to a saved entry. Binding changes are explicit action-bar operations."] = "Выберите комплект предметов и измените его список приоритетов. «Общие» делает комплект общим для всех профилей. Стрелки меняют приоритет предметов. «Привязать комплект» берёт доступный предмет для размещения на панели команд; метка привязки при отвязке вне боя удаляет соответствующие привязанные действия с панелей. «Сбросить» восстанавливает поставляемый комплект. Ищите или перетаскивайте предметы в поля ссылок. «Применить» сохраняет настройки; «Отменить изменения» отбрасывает правки сохранённой записи. Изменения привязок — явные операции с панелями команд."
-- en: "Press Enter or leave a text field to stage its value; Apply saves the draft. Invalid text stays red and must be corrected before Apply; Discard can abandon it. Searchable selectors open on click and filter as you type. Section headings collapse or expand their contents."
L["Press Enter or leave a text field to stage its value; Apply saves the draft. Invalid text stays red and must be corrected before Apply; Discard can abandon it. Searchable selectors open on click and filter as you type. Section headings collapse or expand their contents."] = "Нажмите Enter или покиньте текстовое поле, чтобы подготовить значение; «Применить» сохраняет черновик. Некорректный текст остаётся красным, и его нужно исправить до применения; «Отменить изменения» может его отбросить. Списки с поиском открываются по нажатию и фильтруются по мере ввода. Заголовки разделов сворачивают и разворачивают содержимое."
-- en: "Apply changes to this selected item list. Other settings keep their own Apply action."
L["Apply changes to this selected item list. Other settings keep their own Apply action."] = "Применить изменения к этому выбранному списку предметов. У других настроек своя кнопка «Применить»."
-- en: "Choose an item list before editing."
L["Choose an item list before editing."] = "Перед правкой выберите список предметов."
-- en: "The item list changed elsewhere. Close and reopen it before applying."
L["The item list changed elsewhere. Close and reopen it before applying."] = "Список предметов изменён в другом месте. Закройте и откройте его заново перед применением."
-- en: "Editing this list"
L["Editing this list"] = "Правка этого списка"
-- en: "This window edits only the item list you opened. Search or drag items into the fields, then arrange preferred items first. A named item set is shared by its other users; a custom list belongs to the calling condition or action draft. Applying this list does not apply the parent editor."
L["Help.ItemSets.popup.overview"] = "Это окно правит только открытый вами список предметов. Ищите или перетаскивайте предметы в поля, затем расставьте предпочтительные первыми. Именованный комплект общий для всех, кто его использует; свой список принадлежит черновику вызывающего условия или действия. Применение этого списка не применяет родительский редактор."
-- en: "Use a row's red trash can to remove that entry from the draft list. This does not delete a named item set or remove an item from your inventory. The removal takes effect when you Apply this list."
L["Help.ItemSets.popup.delete"] = "Красная корзина в строке удаляет эту запись из черновика списка. Именованный комплект при этом не удаляется, а предмет не пропадает из инвентаря. Удаление вступает в силу, когда вы примените список."
-- en: "Apply validates every entry and writes the edited list back to its original owner. Discard closes without changing it. Closing with pending edits offers Apply, Discard or Cancel; Cancel keeps this window open. View Changes compares the original list with this draft. If the original list changed elsewhere, close and reopen it before applying."
L["Help.ItemSets.popup.save"] = "«Применить» проверяет каждую запись и записывает изменённый список обратно его исходному владельцу. «Отменить изменения» закрывает окно без изменений. При закрытии с ожидающими правками предлагается «Применить», «Отменить изменения» или «Отмена»; «Отмена» оставляет окно открытым. «Показать изменения» сравнивает исходный список с этим черновиком. Если исходный список изменился в другом месте, закройте и откройте его заново перед применением."
-- en: "Native settings page unavailable: %s"
L["Native settings page unavailable: %s"] = "Встроенная страница настроек недоступна: %s"
-- en: "The native rotation editor is unavailable."
L["The native rotation editor is unavailable."] = "Встроенный редактор ротаций недоступен."
-- en: "Required"
L["Required"] = "Обязательное"
-- en: "Required field references need review. Apply keeps the displayed root requirements."
L["Required field references need review. Apply keeps the displayed root requirements."] = "Ссылки на обязательные поля требуют проверки. «Применить» сохраняет показанные требования корневого уровня."
-- en: "Required root fields must have a value before this condition can run. Rename, reorder and duplicate keep this flag; removing the field removes its requirement. Moving it into a nested structure makes it optional. Undo restores both. Callback code is unchanged."
L["Required root fields must have a value before this condition can run. Rename, reorder and duplicate keep this flag; removing the field removes its requirement. Moving it into a nested structure makes it optional. Undo restores both. Callback code is unchanged."] = "Обязательные поля корневого уровня должны иметь значение, прежде чем условие сможет выполняться. Переименование, перемещение и дублирование сохраняют этот флаг; удаление поля снимает требование. Перемещение во вложенную структуру делает поле необязательным. «Отменить» восстанавливает оба состояния. Код обратного вызова не меняется."
-- en: "Copy condition description"
L["Copy condition description"] = "Копировать описание условия"
-- en: "This condition exceeds the supported editor limits."
L["This condition exceeds the supported editor limits."] = "Это условие превышает поддерживаемые редактором пределы."
-- en: "Proc Glow"
L["Proc Glow"] = "Свечение срабатывания"
-- en: "Loop duration"
L["Loop duration"] = "Длительность цикла"
-- en: "Start burst"
L["Start burst"] = "Начальная вспышка"
-- en: "Proc Glow is unavailable on this client; Pixel glow will be used."
L["Proc Glow is unavailable on this client; Pixel glow will be used."] = "«Свечение срабатывания» недоступно на этом клиенте; будет использовано свечение «Пиксели»."
-- en: "Proc Glow: use the animated actionbar proc border from LibCustomGlow. Rotation Master checks the required game artwork and animation support before using it. Unsupported clients use Pixel glow instead; the definition remains portable. Color and offsets come from the profile or the cooldown."
L["Help.Effects.type.proc"] = "Свечение срабатывания: анимированная рамка срабатывания на панели команд из LibCustomGlow. Перед использованием Rotation Master проверяет наличие нужных игровых изображений и поддержки анимации. На неподдерживаемых клиентах используется свечение «Пиксели»; определение остаётся переносимым. Цвет и смещения берутся из профиля или восстановления."
-- en: "Time in seconds for one repeating proc-border animation, from 0.1 to 5. Use the slider or enter an exact value in its number field. Changing the value updates the preview."
L["Help.Effects.proc.duration"] = "Время в секундах на один повтор анимации рамки срабатывания, от 0.1 до 5. Используйте ползунок или введите точное значение в числовое поле. Изменение значения обновляет предпросмотр."
-- en: "Play the opening burst when this highlight first appears, then repeat its border animation. Off by default. Refreshing an already visible Proc Glow does not restart the burst."
